// ── AUTH SCREEN ─────────────────────────────────────────────────────────────
function AuthScreen({onAuth}) {
  const [mode,setMode]=useState('login');
  const [email,setEmail]=useState('');
  const [pass,setPass]=useState('');
  const [name,setName]=useState('');
  const [err,setErr]=useState('');
  const [msg,setMsg]=useState('');
  const [busy,setBusy]=useState(false);

  const submit = async () => {
    setErr(''); setMsg(''); setBusy(true);
    try {
      if(mode==='login'){
        const {data,error}=await sb.auth.signInWithPassword({email,password:pass});
        if(error) throw error;
        onAuth(data.user);
      } else if(mode==='signup'){
        const {error}=await sb.auth.signUp({email,password:pass,options:{data:{full_name:name,role:'supervisor'}}});
        if(error) throw error;
        setMsg('Check your email to confirm your account, then sign in.');
        setMode('login');
      } else {
        const {error}=await sb.auth.resetPasswordForEmail(email);
        if(error) throw error;
        setMsg('Password reset email sent.'); setMode('login');
      }
    } catch(e){ setErr(e.message); }
    setBusy(false);
  };

  return (
    <div style={{minHeight:'100vh',background:C.bg,display:'flex',alignItems:'center',justifyContent:'center',padding:20}}>
      <div style={{width:'100%',maxWidth:420}}>
        <div style={{textAlign:'center',marginBottom:32}}>
          <img src={LOGO} style={{height:'80px',width:'auto',display:'inline-block',marginBottom:16}} alt="Pacific Homes"/>
          <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t2,letterSpacing:2,marginTop:4}}>SITE MANAGEMENT PORTAL</div>
        </div>
        <div style={{background:C.surface,border:'1px solid '+C.border,borderRadius:16,padding:28}}>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:22,letterSpacing:2,marginBottom:20}}>
            {mode==='login'?'SIGN IN':mode==='signup'?'CREATE ACCOUNT':'RESET PASSWORD'}
          </div>
          {err&&<div style={{background:C.red+'20',border:'1px solid '+C.red,borderRadius:8,padding:'10px 14px',fontSize:13,color:C.red,marginBottom:14}}>{err}</div>}
          {msg&&<div style={{background:C.green+'20',border:'1px solid '+C.green,borderRadius:8,padding:'10px 14px',fontSize:13,color:C.green,marginBottom:14}}>{msg}</div>}
          {mode==='signup'&&<div style={{marginBottom:14}}><label style={LS}>FULL NAME</label><input value={name} onChange={e=>setName(e.target.value)} placeholder="Your name" style={IS()}/></div>}
          <div style={{marginBottom:14}}><label style={LS}>EMAIL</label><input value={email} onChange={e=>setEmail(e.target.value)} type="email" placeholder="you@company.com" style={IS()} onKeyDown={e=>e.key==='Enter'&&submit()}/></div>
          {mode!=='reset'&&<div style={{marginBottom:22}}><label style={LS}>PASSWORD</label><input value={pass} onChange={e=>setPass(e.target.value)} type="password" placeholder="••••••••" style={IS()} onKeyDown={e=>e.key==='Enter'&&submit()}/></div>}
          <button onClick={submit} disabled={busy} style={{...BS(C.amber),width:'100%',padding:'13px',fontSize:16,letterSpacing:2,opacity:busy?0.7:1}}>
            {busy?'PLEASE WAIT…':mode==='login'?'SIGN IN':mode==='signup'?'CREATE ACCOUNT':'SEND RESET EMAIL'}
          </button>
          <div style={{marginTop:16,display:'flex',flexDirection:'column',gap:8,alignItems:'center'}}>
            {mode==='login'&&<>
              <button onClick={()=>{setMode('signup');setErr('');}} style={{background:'transparent',border:'none',color:C.blue,cursor:'pointer',fontSize:13}}>No account? Sign up</button>
              <button onClick={()=>{setMode('reset');setErr('');}} style={{background:'transparent',border:'none',color:C.t3,cursor:'pointer',fontSize:12}}>Forgot password?</button>
            </>}
            {mode!=='login'&&<button onClick={()=>{setMode('login');setErr('');}} style={{background:'transparent',border:'none',color:C.blue,cursor:'pointer',fontSize:13}}>Back to sign in</button>}
          </div>
        </div>
      </div>
    </div>
  );
}

// ── ROOT APP ─────────────────────────────────────────────────────────────────
function App() {
  // Optimistic restore: if a returning user has BOTH a cached user marker and
  // cached profile, render immediately while getSession() confirms in the
  // background. Data is RLS-protected, so a stale optimistic render is safe —
  // an invalid session simply fails the refresh and signs them out.
  const cachedProfile=lsLoadProfile();
  const cachedUser=lsLoadUser();
  const canOptimisticRender=!!(cachedProfile&&cachedUser);
  const [user,setUser]=useState(()=>canOptimisticRender?cachedUser:null);
  const [profile,setProfile]=useState(()=>cachedProfile);
  const [profiles,setProfiles]=useState([]); // all registered users
  const [loading,setLoading]=useState(!canOptimisticRender);
  const [projects,setProjects]=useState(()=>{try{return lsLoad()||[];}catch{return [];}});
  const [toast,setToast]=useState('');
  const [sbOk,setSbOk]=useState(true);
  const [dataReady,setDataReady]=useState(false);
  const [supabaseLoaded,setSupabaseLoaded]=useState(false);

  const showToast=msg=>{setToast(msg);setTimeout(()=>setToast(''),4000);};

  useEffect(()=>{
    if(!isSupabaseReady()){
      setSbOk(false);
      setProjects(lsLoad());
      setProfile({role:'admin',full_name:'Local User',id:'local'});
      setUser({id:'local',email:'local'});
      setLoading(false);
      setDataReady(true);
      return;
    }

    sb.auth.getSession().then(({data:{session}})=>{
      if(session){
        setUser(session.user);
        lsSaveUser(session.user);
      } else {
        // No valid session. If we optimistically rendered from cache, undo it.
        try{localStorage.removeItem(USER_KEY);localStorage.removeItem(PROFILE_KEY);localStorage.removeItem(LS_KEY);}catch(e){}
        setUser(null);setProfile(null);setProjects([]);
        setLoading(false);
      }
    }).catch(()=>{
      setLoading(false); // show login on error - don't fake local user
    });
    const {data:{subscription}}=sb.auth.onAuthStateChange((_,session)=>{
      if(session){setUser(session.user);lsSaveUser(session.user);}
      else {try{localStorage.removeItem(USER_KEY);localStorage.removeItem(PROFILE_KEY);}catch(e){}setUser(null);setProfile(null);setLoading(false);}
    });
    return ()=>{ subscription.unsubscribe(); };
  },[]);

  useEffect(()=>{
    if(!user||user.id==='local') return;

    const dataTimeout=setTimeout(()=>{
      setProjects(prev=>prev.length?prev:lsLoad());
      setProfile(prev=>prev||{role:'admin',full_name:user.email||'',id:user.id,email:user.email||''});
      setLoading(false);
      setDataReady(true);
      setSupabaseLoaded(true); // stop the sync bar even on timeout
    },12000);

    // Load profile, projects, and all-profiles IN PARALLEL (not chained)
    // so a slow profile query doesn't block project loading
    Promise.all([
      sb.from('profiles').select('*').eq('id',user.id).single().then(r=>r.data).catch(()=>null),
      dbProjects().catch(e=>{console.error('dbProjects failed:',e);return null;}),
      dbProfiles().catch(()=>[])
    ]).then(([prof,projs,profs])=>{
      clearTimeout(dataTimeout);
      const resolvedProfile=prof||{role:'admin',full_name:user.email||'',id:user.id,email:user.email||''};
      setProfile(resolvedProfile);
      lsSaveProfile(resolvedProfile);
      setProfiles(profs||[]);
      if(projs!==null){
        // Supabase returned projects successfully
        const local=lsLoad();
        const merged=[...projs];
        local.forEach(lp=>{if(!merged.find(sp=>sp.id===lp.id))merged.push(lp);});
        setProjects(merged);
        lsSave(merged);
      } else {
        // projects fetch failed - keep whatever we have / cache
        setProjects(prev=>prev.length?prev:lsLoad());
      }
      setLoading(false);
      setDataReady(true);
      setSupabaseLoaded(true);
    }).catch(e=>{
      console.error('Data load failed:',e);
      clearTimeout(dataTimeout);
      setProjects(prev=>prev.length?prev:lsLoad());
      setProfile(prev=>prev||{role:'admin',full_name:user.email||'',id:user.id,email:user.email||''});
      setLoading(false);
      setDataReady(true);
      setSupabaseLoaded(true);
    });

    const ch=sb.channel('proj_ch')
      .on('postgres_changes',{event:'*',schema:'public',table:'sc_projects'},payload=>{
        if(payload.eventType==='DELETE'){
          setProjects(p=>{const next=p.filter(x=>x.id!==payload.old.id);lsSave(next);return next;});
        } else {
          const u={...payload.new.data,id:payload.new.id,_updated:payload.new.updated_at};
          setProjects(p=>{const i=p.findIndex(x=>x.id===u.id);const next=i>=0?p.map((x,j)=>j===i?u:x):[u,...p];lsSave(next);return next;});
        }
      }).subscribe();
    return ()=>{clearTimeout(dataTimeout);sb.removeChannel(ch);};
  },[user]);

  const saveProject=useCallback(async p=>{
    setProjects(prev=>{const next=prev.map(x=>x.id===p.id?p:x);lsSave(next);return next;});
    if(sbOk&&user?.id!=='local'){try{await dbSave(p);}catch(e){showToast("⚠️ Cloud save failed — saved locally");}}
  },[sbOk,user]);

  const createProject=useCallback(async form=>{
    const stages=form.stages||buildDefaultStages();
    const p={id:uid(),name:form.name,location:form.location,client:form.client,startDate:form.startDate,currentStage:0,stages,supervisors:form.supervisors||[],assignedUserIds:form.assignedUserIds||[],status:'active',archivedAt:null,deletedAt:null,color:form.color||randProjColor(),createdAt:new Date().toISOString()};
    setProjects(prev=>{const next=[p,...prev];lsSave(next);return next;});
    if(sbOk&&user?.id!=='local'){try{await dbSave(p);}catch(e){showToast("⚠️ Cloud save failed — saved locally");}}
    return p.id;
  },[sbOk,user]);

  const archiveProject=useCallback(async id=>{
    setProjects(prev=>{const next=prev.map(p=>p.id===id?{...p,status:'archived',archivedAt:new Date().toISOString()}:p);lsSave(next);return next;});
    if(sbOk&&user?.id!=='local'){
      const p=projects.find(x=>x.id===id);
      if(p) try{await dbSave({...p,status:'archived',archivedAt:new Date().toISOString()});}catch(e){}
    }
  },[sbOk,user,projects]);

  const softDeleteProject=useCallback(async id=>{
    const now=new Date().toISOString();
    setProjects(prev=>{const next=prev.map(p=>p.id===id?{...p,status:'deleted',deletedAt:now}:p);lsSave(next);return next;});
    if(sbOk&&user?.id!=='local'){
      const p=projects.find(x=>x.id===id);
      if(p) try{await dbSave({...p,status:'deleted',deletedAt:now});}catch(e){}
    }
  },[sbOk,user,projects]);

  const restoreProject=useCallback(async id=>{
    setProjects(prev=>{const next=prev.map(p=>p.id===id?{...p,status:'active',archivedAt:null,deletedAt:null}:p);lsSave(next);return next;});
    if(sbOk&&user?.id!=='local'){
      const p=projects.find(x=>x.id===id);
      if(p) try{await dbSave({...p,status:'active',archivedAt:null,deletedAt:null});}catch(e){}
    }
  },[sbOk,user,projects]);

  const permanentDelete=useCallback(async id=>{
    setProjects(prev=>{const next=prev.filter(p=>p.id!==id);lsSave(next);return next;});
    if(sbOk&&user?.id!=='local'){try{await dbDel(id);}catch(e){}}
  },[sbOk,user]);

  const deleteProject=permanentDelete; // legacy alias

  const [viewAs,setViewAs]=useState('admin');

  const handleSignOut=async()=>{
    if(sbOk&&user?.id!=='local') await sb.auth.signOut();
    try{localStorage.removeItem(USER_KEY);localStorage.removeItem(PROFILE_KEY);localStorage.removeItem(LS_KEY);}catch(e){}
    setProjects([]);setProfile(null);setUser(null);
  };

  if(!user&&!loading) return <AuthScreen onAuth={setUser}/>;
  // Only block on Splash if we truly have nothing to show yet (no user, or a
  // logged-in user with no cached profile). A cached profile lets us render
  // instantly while fresh data refreshes in the background.
  if(!user) return <Splash/>;
  if(!profile&&user.id!=='local') return <Splash/>;

  const isAdmin=profile?.role==='admin'||profile?.role==='superadmin'||profile?.role==='super_admin';
  // Admin always sees admin view unless they explicitly switched to supervisor
  const showAdmin=isAdmin&&viewAs!=='supervisor';
  const onSwitchView=isAdmin?()=>setViewAs(v=>{
    const next=v==='admin'?'supervisor':'admin';
    try{localStorage.setItem('ph_viewAs',next);}catch{}
    return next;
  }):null;

  const props={user,profile,profiles,projects,supabaseLoaded,onSave:saveProject,onCreate:createProject,onDelete:deleteProject,onArchive:archiveProject,onSoftDelete:softDeleteProject,onRestore:restoreProject,onPermanentDelete:permanentDelete,onSignOut:handleSignOut,showToast,sbOk,onSwitchView};

  return (
    <div>
      {!sbOk&&(
        <div style={{background:'#FEF3C7',color:'#92400E',padding:'9px 16px',fontFamily:"'Barlow',sans-serif",fontSize:13,textAlign:'center',borderBottom:'1px solid #FCD34D'}}>
          ⚠️ <strong>Cloud not connected</strong> — data is saved on this device. Add your Supabase key to enable team sync.
        </div>
      )}
      {showAdmin ? <AdminApp {...props} onSwitchView={onSwitchView}/> : <SupervisorApp {...props} onSwitchView={onSwitchView}/>}
      {toast&&<div style={{position:'fixed',bottom:24,left:'50%',transform:'translateX(-50%)',background:C.card,border:'1px solid '+C.border,borderRadius:10,padding:'12px 20px',color:C.t1,fontSize:13,zIndex:9999,boxShadow:'0 4px 20px #000a',whiteSpace:'nowrap'}}>{toast}</div>}
    </div>
  );
}

// ── ADMIN APP ────────────────────────────────────────────────────────────────
function AdminApp({user,profile,profiles,projects,supabaseLoaded,onSave,onCreate,onDelete,onArchive,onSoftDelete,onRestore,onPermanentDelete,onSignOut,showToast,onSwitchView,viewAs}) {
  const [section,setSection]=useState('dashboard');
  const [selProject,setSelProject]=useState(null);
  const [adminScreen,setAdminScreen]=useState('main'); // main | project
  const [activeProjectId,setActiveProjectId]=useState(null);
  const [templates,setTemplates]=useState([]);
  const [loadingTemplates,setLoadingTemplates]=useState(false);

  useEffect(()=>{
    if(section==='templates'&&!templates.length){
      setLoadingTemplates(true);
      dbTemplates().then(t=>{setTemplates(t);setLoadingTemplates(false);});
    }
  },[section]);

  const activeProjects=projects.filter(p=>!p.status||p.status==='active');

  // Full project editing screen for admins
  const activeProject=projects.find(p=>p.id===activeProjectId);
  if(adminScreen==='create'){
    return <CreateScreen templates={templates} profiles={profiles} onBack={()=>setAdminScreen('main')} onCreate={async form=>{const id=await onCreate(form);setActiveProjectId(id);setAdminScreen('project');}}/>;
  }

  if(adminScreen==='project'&&activeProject){
    return <ProjectScreen
      project={activeProject}
      profiles={profiles}
      user={user}
      profile={profile}
      onSave={onSave}
      onArchive={onArchive}
      onSoftDelete={onSoftDelete}
      onDelete={async()=>{await onSoftDelete(activeProject.id);setAdminScreen('main');setActiveProjectId(null);}}
      onBack={()=>{setAdminScreen('main');setActiveProjectId(null);}}
    />;
  }
  const archivedProjects=projects.filter(p=>p.status==='archived');
  const deletedProjects=projects.filter(p=>p.status==='deleted').filter(p=>{
    if(!p.deletedAt) return true;
    return (Date.now()-new Date(p.deletedAt).getTime())<60*24*60*60*1000; // 60 days
  });
  const total=activeProjects.length;
  const active=activeProjects.filter(p=>p.currentStage<p.stages.length-1).length;
  const completed=activeProjects.filter(p=>p.currentStage>=p.stages.length-1).length;
  const allTasks=activeProjects.flatMap(p=>p.stages.flatMap(s=>s.tasks));
  const doneTasks=allTasks.filter(t=>t.status==='done').length;
  const pct=allTasks.length?Math.round((doneTasks/allTasks.length)*100):0;

  const NAV=[
    {id:'dashboard',icon:"📊",label:'DASHBOARD',count:null},
    {id:'projects',icon:"📁",label:'PROJECTS',count:activeProjects.length},
    {id:'archive',icon:"📦",label:'ARCHIVE',count:archivedProjects.length||null},
    {id:'trash',icon:"🗑️",label:'TRASH',count:deletedProjects.length||null},
    {id:'reports',icon:"📋",label:'REPORTS',count:null},
    {id:'templates',icon:"📐",label:'TEMPLATES',count:null},
    {id:'users',icon:"⚙️",label:'USERS',count:profiles.length||null},
  ];

  return (
    <div style={{minHeight:'100vh',background:C.bg,display:'flex'}}>
      {/* ── Left Sidebar (Accounts-style) ─────────────────────────── */}
      <div className="admin-sidebar" style={{width:248,background:'#0D1B3E',display:'flex',flexDirection:'column',flexShrink:0,height:'100vh',position:'sticky',top:0}}>
        {/* Logo + portal label */}
        <div style={{padding:'22px 22px 18px'}}>
          <img src={LOGO} style={{height:'46px',width:'auto',display:'block',marginBottom:8}} alt="Paciffic Homes"/>
          <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.amber,letterSpacing:2}}>ADMIN PORTAL</div>
        </div>
        {/* Nav items */}
        <div style={{flex:1,overflowY:'auto',padding:'4px 12px'}}>
          {NAV.map(n=>{
            const on=section===n.id;
            return(
              <button key={n.id} onClick={()=>{setSection(n.id);setSelProject(null);setAdminScreen('main');setActiveProjectId(null);}}
                style={{width:'100%',display:'flex',alignItems:'center',gap:12,padding:'11px 14px',marginBottom:2,borderRadius:9,border:'none',cursor:'pointer',textAlign:'left',
                  background:on?C.amber:'transparent',
                  color:on?'#0D1B3E':'#94A3B8',
                  fontFamily:"'Barlow',sans-serif",fontWeight:on?700:500,fontSize:14,transition:'all 0.12s'}}
                onMouseEnter={e=>{if(!on)e.currentTarget.style.background='#16294A';}}
                onMouseLeave={e=>{if(!on)e.currentTarget.style.background='transparent';}}>
                <span style={{fontSize:17,width:20,textAlign:'center',flexShrink:0}}>{n.icon}</span>
                <span style={{flex:1}}>{n.label.charAt(0)+n.label.slice(1).toLowerCase()}</span>
                {n.count!=null&&<span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:11,fontWeight:400,color:on?'#0D1B3E':'#64748B'}}>{n.count}</span>}
              </button>
            );
          })}
        </div>
        {/* User block pinned at bottom */}
        <div style={{padding:'16px 18px',borderTop:'1px solid #1E3A5F'}}>
          <div style={{fontFamily:"'Barlow',sans-serif",fontWeight:600,fontSize:14,color:'#fff',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{profile?.full_name||user.email}</div>
          <div style={{fontSize:11,color:'#64748B',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap',marginBottom:8}}>{user.email}</div>
          <div style={{display:'inline-block',background:'#1E3A5F',borderRadius:5,padding:'3px 9px',fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:'#94A3B8',letterSpacing:1,marginBottom:10}}>{(profile?.role||'admin').replace('_',' ').toUpperCase()}</div>
          <button onClick={onSignOut} style={{width:'100%',background:'transparent',border:'1px solid #1E3A5F',borderRadius:7,padding:'8px',color:'#94A3B8',cursor:'pointer',fontFamily:"'Barlow',sans-serif",fontSize:13}}
            onMouseEnter={e=>{e.currentTarget.style.background='#16294A';}} onMouseLeave={e=>{e.currentTarget.style.background='transparent';}}>Sign out</button>
          <div style={{textAlign:'center',marginTop:8,fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:'#3E5170',letterSpacing:1}}>{APP_VERSION}</div>
        </div>
      </div>

      {/* ── Main Content ──────────────────────────────────────────── */}
      <div className="admin-content" style={{flex:1,minWidth:0,overflow:'auto',height:'100vh',paddingBottom:'80px'}}>
        {/* Content header with action buttons */}
        <div style={{display:'flex',alignItems:'center',justifyContent:'flex-end',gap:10,padding:'16px 28px',flexWrap:'wrap'}}>
          {onSwitchView&&<button onClick={onSwitchView} style={{...BS('transparent',C.blue),border:'1px solid '+C.blue+'40',padding:'8px 14px',fontSize:13,letterSpacing:0.3,flexShrink:0}}>👷 SUPERVISOR VIEW</button>}
          <button onClick={()=>setAdminScreen('create')} style={{...BS(C.amber),padding:'9px 18px',fontSize:14,letterSpacing:0.5,flexShrink:0}}>+ NEW PROJECT</button>
        </div>
        <div style={{padding:'4px 28px 28px'}}>
        {section==='dashboard'&&<AdminDashboard projects={activeProjects} supabaseLoaded={supabaseLoaded} stats={{total,active,completed,allTasks:allTasks.length,doneTasks,pct}} onSave={onSave} onOpenProject={p=>{setActiveProjectId(p.id);setAdminScreen('project');}} onGoProjects={()=>setSection('projects')}/>}
        {section==='projects'&&<AdminProjectsList projects={activeProjects} onSelect={p=>{setActiveProjectId(p.id);setAdminScreen('project');}} onDetail={p=>{setSelProject(p);}} selProject={selProject} profiles={profiles} onSave={onSave} onSoftDelete={onSoftDelete} onArchive={onArchive} onBack={()=>setSelProject(null)} onDelete={async id=>{await onDelete(id);setSelProject(null);}} user={user}/>}
        {section==='archive'&&<AdminArchive projects={archivedProjects} user={user} onRestore={onRestore} onSoftDelete={onSoftDelete}/>}
        {section==='trash'&&<AdminTrash projects={deletedProjects} user={user} onRestore={onRestore} onPermanentDelete={onPermanentDelete}/>}
        {section==='reports'&&<AdminReports projects={activeProjects}/>}
        {section==='templates'&&<AdminTemplates templates={templates} loading={loadingTemplates} onSave={async t=>{await dbSaveTemplate(t);setTemplates(prev=>{const i=prev.findIndex(x=>x.id===t.id);return i>=0?prev.map((x,j)=>j===i?t:x):[...prev,t];});showToast('Template saved');}} onDelete={async id=>{await dbDelTemplate(id);setTemplates(prev=>prev.filter(t=>t.id!==id));showToast('Template deleted');}}/>}
        {section==='users'&&<AdminUsers profiles={profiles} loading={false} currentUserId={user.id} onRoleChange={async(id,role)=>{await dbSetRole(id,role);showToast('Role updated — user must sign out and back in to see changes');}}/>}
        </div>
      </div>

      {/* ── Mobile Bottom Nav (unchanged behavior) ────────────────── */}
      <div className="admin-mobile-nav" style={{position:'fixed',bottom:0,left:0,right:0,background:'#0D1B3E',borderTop:'2px solid '+C.amber,display:'none',zIndex:100,padding:'4px 0'}}>
        {NAV.map(n=>(
          <button key={n.id} onClick={()=>{setSection(n.id);setSelProject(null);setAdminScreen('main');setActiveProjectId(null);}}
            style={{flex:1,padding:'8px 4px',border:'none',background:'transparent',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:9,letterSpacing:0.5,color:section===n.id?C.amber:'#64748B',display:'flex',flexDirection:'column',alignItems:'center',gap:3,cursor:'pointer'}}>
            <span style={{fontSize:20}}>{n.icon}</span>
            <span>{n.label}</span>
          </button>
        ))}
      </div>
    </div>
  );
}

// ── SITE PHOTO GALLERY ───────────────────────────────────────────────────────
function SitePhotoGallery({projects,onOpenProject}) {
  const [photos,setPhotos]=useState([]);
  const [loading,setLoading]=useState(true);
  const [lightbox,setLightbox]=useState(null);

  useEffect(()=>{
    dbRecentPhotos(24).then(rows=>{
      // Enrich with project and stage info
      const enriched=rows.map(ph=>{
        const proj=projects.find(p=>p.id===ph.project_id);
        const stage=proj?.stages?.find(s=>s.id===ph.stage_id);
        return{...ph,projectName:proj?.name||'Unknown',stageName:stage?.name||'',proj};
      });
      setPhotos(enriched);
      setLoading(false);
    }).catch(()=>setLoading(false));
  },[]);

  if(loading) return <div style={{textAlign:'center',padding:'30px',color:C.t3,fontSize:13}}>Loading photos…</div>;
  if(!photos.length) return(
    <div style={{textAlign:'center',padding:'40px',color:C.t3}}>
      <div style={{fontSize:40,marginBottom:10}}>📸</div>
      <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:16,color:C.t2}}>NO SITE PHOTOS YET</div>
      <div style={{fontSize:13,marginTop:6}}>Supervisors can upload photos via the Photos tab on each project</div>
    </div>
  );

  return(
    <div>
      <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(160px,1fr))',gap:8}}>
        {photos.map((ph,i)=>(
          <div key={ph.id||i} style={{position:'relative',paddingTop:'75%',borderRadius:10,overflow:'hidden',cursor:'pointer',boxShadow:'0 2px 8px rgba(0,0,0,0.1)'}}
            onClick={()=>setLightbox(ph)}
            onMouseEnter={e=>{e.currentTarget.querySelector('.overlay').style.opacity='1';}}
            onMouseLeave={e=>{e.currentTarget.querySelector('.overlay').style.opacity='0';}}>
            <img src={ph.data_url} alt={ph.caption||''} style={{position:'absolute',inset:0,width:'100%',height:'100%',objectFit:'cover'}}/>
            <div className="overlay" style={{position:'absolute',inset:0,background:'linear-gradient(to top,rgba(0,0,0,0.8) 0%,transparent 50%)',opacity:0,transition:'opacity 0.2s',display:'flex',flexDirection:'column',justifyContent:'flex-end',padding:'8px'}}>
              <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:12,color:'#fff',lineHeight:1.2}}>{ph.projectName}</div>
              {ph.stageName&&<div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:'rgba(255,255,255,0.7)',marginTop:2}}>{ph.stageName}</div>}
            </div>
          </div>
        ))}
      </div>

      {/* Lightbox */}
      {lightbox&&(
        <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.92)',zIndex:9999,display:'flex',alignItems:'center',justifyContent:'center',flexDirection:'column',padding:20}}
          onClick={()=>setLightbox(null)}>
          <div style={{maxWidth:900,width:'100%'}} onClick={e=>e.stopPropagation()}>
            <img src={lightbox.data_url} alt={lightbox.caption||''} style={{width:'100%',maxHeight:'70vh',objectFit:'contain',borderRadius:12,display:'block'}}/>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginTop:12,flexWrap:'wrap',gap:10}}>
              <div>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:18,color:'#fff'}}>{lightbox.projectName}</div>
                <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:11,color:'rgba(255,255,255,0.6)'}}>{lightbox.stageName} · {lightbox.caption||'No caption'} · {new Date(lightbox.taken_at).toLocaleDateString('en-AU',{day:'2-digit',month:'short',year:'numeric'})}</div>
              </div>
              <div style={{display:'flex',gap:10}}>
                {lightbox.proj&&<button onClick={()=>{onOpenProject&&onOpenProject(lightbox.proj);setLightbox(null);}} style={{...BS(C.amber),padding:'8px 16px',fontSize:13}}>OPEN PROJECT →</button>}
                <button onClick={()=>setLightbox(null)} style={{...BS('transparent','rgba(255,255,255,0.6)'),border:'1px solid rgba(255,255,255,0.3)',padding:'8px 16px',fontSize:13}}>CLOSE</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}


function AdminDashboard({projects,stats,onSave,onOpenProject,onGoProjects,supabaseLoaded}) {
  const recent=[...projects].sort((a,b)=>new Date(b._updated||b.createdAt)-new Date(a._updated||a.createdAt)).slice(0,8);
  const noteItems=[];
  projects.forEach(p=>{p.stages.forEach(s=>{if(s.notedAt&&(s.achievements||s.notes||s.nextSteps))noteItems.push({p,s,notedAt:s.notedAt,notedBy:s.notedBy||''});});});
  noteItems.sort((a,b)=>new Date(b.notedAt)-new Date(a.notedAt));
  const now=new Date(); // use local time, AEST conversion was causing Invalid Date on some browsers
  const hour=now.getHours();
  const greetWord=hour<12?'GOOD MORNING':hour<17?'GOOD AFTERNOON':'GOOD EVENING';
  const dateStr=now.toLocaleDateString('en-AU',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
  const statCards=[
    {label:'TOTAL PROJECTS',val:stats.total,color:C.t1,bg:'#EEF2FF',sub:'all projects'},
    {label:'ACTIVE',val:stats.active,color:C.amber,bg:C.tintAmber,sub:'in progress'},
    {label:'COMPLETED',val:stats.completed,color:C.green,bg:C.tintGreen,sub:'handed over'},
    {label:'TASKS DONE',val:stats.doneTasks+'/'+stats.allTasks,color:C.blue,bg:C.tintBlue,sub:'across all stages'},
    {label:'COMPLETION',val:stats.pct+'%',color:C.purple,bg:C.tintPurple,sub:'overall progress'},
  ];
  return (
    <div>
      {!supabaseLoaded&&!(projects&&projects.length)&&<div style={{background:C.amber+'15',border:'1px solid '+C.amber+'40',borderRadius:8,padding:'8px 14px',marginBottom:14,display:'flex',alignItems:'center',gap:10,fontFamily:"'JetBrains Mono',monospace",fontSize:11,color:C.amber}}><div style={{width:14,height:14,border:'2px solid '+C.amber+'40',borderTop:'2px solid '+C.amber,borderRadius:'50%',animation:'spin 1s linear infinite'}}/>Syncing latest data...</div>}
      <SafeActivityFeed projects={projects} onSave={onSave}/>
      <div style={{fontFamily:C.serif,fontWeight:600,fontSize:30,color:C.t1,marginBottom:2,letterSpacing:'-0.01em'}}>{greetWord.charAt(0)+greetWord.slice(1).toLowerCase()}</div>
      <div style={{fontSize:13,color:C.t3,marginBottom:22}}>{dateStr} · AEST</div>
      <div className="stat-grid" style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(180px,1fr))',gap:14,marginBottom:26}}>
        {statCards.map(c=>(
          <button key={c.label} onClick={onGoProjects}
            style={{background:c.bg,border:'1px solid '+c.color+'22',borderRadius:14,padding:'18px 18px',textAlign:'left',cursor:'pointer'}}>
            <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t2,letterSpacing:1,marginBottom:10,fontWeight:600}}>{c.label}</div>
            <div style={{fontFamily:C.serif,fontWeight:600,fontSize:34,color:c.color,lineHeight:1,marginBottom:8}}>{c.val}</div>
            <div style={{fontSize:12,color:C.t3}}>{c.sub}</div>
          </button>
        ))}
      </div>
      <div className="dash-2col" style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:14,marginBottom:14}}>
        <div style={{background:C.card,border:'1px solid '+C.border,borderRadius:12,padding:'16px 18px'}}>
          <div style={{fontFamily:C.serif,fontWeight:600,fontSize:19,color:C.t1,marginBottom:14}}>Recent projects</div>
          {recent.length===0&&<div style={{color:C.t3,fontSize:13,textAlign:'center',padding:'20px'}}>No projects yet</div>}
          {recent.map(p=>{
            const sc=p.stages.length,pct=sc<=1?0:Math.round((p.currentStage/(sc-1))*100),isDone=p.currentStage>=sc-1;
            const tt=p.stages.reduce((a,s)=>a+s.tasks.length,0),td=p.stages.reduce((a,s)=>a+s.tasks.filter(t=>t.status==='done').length,0);
            const pc=p.color||C.amber;
            return(
              <button key={p.id} onClick={()=>onOpenProject&&onOpenProject(p)}
                style={{width:'100%',textAlign:'left',background:C.bg,border:'1px solid '+C.border,borderLeft:'4px solid '+pc,borderRadius:10,padding:'10px 13px',marginBottom:8,cursor:'pointer',display:'flex',alignItems:'center',gap:10}}
                onMouseEnter={e=>{e.currentTarget.style.background=pc+'10';}} onMouseLeave={e=>{e.currentTarget.style.background=C.bg;}}>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:15,color:C.t1,marginBottom:3}}>{p.name}</div>
                  <div style={{fontSize:11,color:C.t2,marginBottom:4}}>{p.location||'No location'} {'·'} {p.stages[p.currentStage]&&p.stages[p.currentStage].name}</div>
                  <div style={{display:'flex',alignItems:'center',gap:6}}>
                    <div style={{flex:1,background:C.border,borderRadius:3,height:5}}>
                      <div style={{width:pct+'%',height:'100%',background:isDone?C.green:pc,borderRadius:3}}/>
                    </div>
                    <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:12,color:isDone?C.green:pc}}>{pct}%</span>
                    <span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.t3}}>{td}/{tt}</span>
                  </div>
                </div>
              </button>
            );
          })}
        </div>
        <div style={{background:C.card,border:'1px solid '+C.border,borderRadius:12,padding:'16px 18px'}}>
          <div style={{fontFamily:C.serif,fontWeight:600,fontSize:19,color:C.t1,marginBottom:14}}>Supervisor notes</div>
          {noteItems.length===0&&<div style={{color:C.t3,fontSize:12,textAlign:'center',padding:'20px'}}>No notes yet</div>}
          {noteItems.slice(0,5).map(({p,s,notedAt,notedBy},i)=>{
            const d=Date.now()-new Date(notedAt).getTime();
            const mins=Math.floor(d/60000),hrs=Math.floor(mins/60),days=Math.floor(hrs/24);
            const ago=days>0?days+'d ago':hrs>0?hrs+'h ago':mins>0?mins+'m ago':'just now';
            return(
              <button key={i} onClick={()=>onOpenProject&&onOpenProject(p)}
                style={{width:'100%',textAlign:'left',background:C.bg,border:'1px solid '+C.border,borderLeft:'3px solid '+C.purple,borderRadius:8,padding:'9px 11px',marginBottom:7,cursor:'pointer'}}
                onMouseEnter={e=>{e.currentTarget.style.background=C.purple+'08';}} onMouseLeave={e=>{e.currentTarget.style.background=C.bg;}}>
                <div style={{display:'flex',justifyContent:'space-between',marginBottom:2}}>
                  <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:13,color:C.t1}}>{p.name}</div>
                  <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.purple}}>{ago}</div>
                </div>
                <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.purple,marginBottom:4}}>{s.name}{notedBy?' '+notedBy.split('@')[0]:''}</div>
                {s.achievements&&<div style={{fontSize:11,color:C.green,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{s.achievements}</div>}
                {s.notes&&<div style={{fontSize:11,color:C.t2,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{s.notes}</div>}
                {s.nextSteps&&<div style={{fontSize:11,color:C.blue,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{s.nextSteps}</div>}
              </button>
            );
          })}
        </div>
      </div>
      <div style={{background:C.card,border:'1px solid '+C.border,borderRadius:12,overflow:'hidden'}}>
        <div style={{padding:'12px 16px',borderBottom:'1px solid '+C.border,display:'flex',alignItems:'center',gap:8}}>
          <div style={{fontFamily:C.serif,fontWeight:600,fontSize:19,color:C.t1}}>Site photo gallery</div>
          <div style={{marginLeft:'auto',fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3}}>CLICK TO ENLARGE</div>
        </div>
        <div style={{padding:'14px 16px'}}>
          <SitePhotoGallery projects={projects} onOpenProject={onOpenProject}/>
        </div>
      </div>
    </div>
  );
}



function AdminPasswordModal({action,actionLabel,onConfirm,onCancel,user}) {
  const [password,setPassword]=useState('');
  const [error,setError]=useState('');
  const [loading,setLoading]=useState(false);

  const verify=async()=>{
    if(!password.trim()){setError('Please enter your password');return;}
    setLoading(true); setError('');
    try{
      if(user.id==='local'){
        if(password.toLowerCase()==='confirm'){onConfirm();return;}
        throw new Error('Type CONFIRM to proceed in local mode');
      }
      const {error:authErr}=await sb.auth.signInWithPassword({email:user.email,password});
      if(authErr) throw new Error('Incorrect password — please try again');
      onConfirm();
    }catch(e){
      setError(e.message||'Incorrect password. Please try again.');
    }finally{
      setLoading(false);
    }
  };

  const icons={archive:"📦",delete:"🗑️",restore:"♻️",permanent:"⚠️"};
  const colors={archive:C.amber,delete:C.red,restore:C.green,permanent:C.red};
  const col=colors[action]||C.amber;

  return(
    <div style={{position:'fixed',inset:0,background:'#000c',display:'flex',alignItems:'center',justifyContent:'center',zIndex:9999,padding:20}}>
      <div style={{background:C.surface,border:'1px solid '+col,borderRadius:16,padding:28,maxWidth:400,width:'100%'}}>
        <div style={{textAlign:'center',marginBottom:20}}>
          <div style={{fontSize:40,marginBottom:10}}>{icons[action]||"🔐"}</div>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:22,color:C.t1,marginBottom:6}}>{actionLabel}</div>
          <div style={{fontSize:13,color:C.t2}}>Enter your admin password to confirm this action</div>
        </div>
        {error&&<div style={{background:C.red+'20',border:'1px solid '+C.red,borderRadius:8,padding:'10px 14px',fontSize:13,color:C.red,marginBottom:14}}>{error}</div>}
        <input
          type="password" value={password} onChange={e=>setPassword(e.target.value)}
          onKeyDown={e=>e.key==='Enter'&&verify()}
          placeholder="Enter your password"
          autoFocus
          style={{width:'100%',background:C.bg,border:'1px solid '+C.border,borderRadius:8,padding:'11px 14px',color:C.t1,fontFamily:"'Barlow',sans-serif",fontSize:14,outline:'none',marginBottom:16}}
        />
        <div style={{display:'flex',gap:10}}>
          <button onClick={onCancel} style={{...BS('transparent',C.t2),flex:1,border:'1px solid '+C.border,padding:'11px'}}>CANCEL</button>
          <button onClick={verify} disabled={loading} style={{...BS(col,col===C.amber?'#000':'#fff'),flex:2,padding:'11px',opacity:loading?0.7:1}}>
            {loading?'VERIFYING…':'CONFIRM'}
          </button>
        </div>
      </div>
    </div>
  );
}

// ── ADMIN ARCHIVE ─────────────────────────────────────────────────────────────
function AdminArchive({projects,user,onRestore,onSoftDelete}) {
  const [modal,setModal]=useState(null); // {action,id,label}

  const confirm=()=>{
    if(modal.action==='restore') onRestore(modal.id);
    if(modal.action==='delete') onSoftDelete(modal.id);
    setModal(null);
  };

  return(
    <div>
      <Lbl style={{marginBottom:4}}>ARCHIVED PROJECTS ({projects.length})</Lbl>
      <div style={{color:C.t3,fontSize:13,marginBottom:20}}>Archived projects are hidden from the main view. Restore them to make them active again.</div>
      {projects.length===0&&(
        <div style={{textAlign:'center',padding:'60px 0',color:C.t3}}>
          <div style={{fontSize:48,marginBottom:14}}>📦</div>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:20,color:C.t2,marginBottom:6}}>NO ARCHIVED PROJECTS</div>
          <div style={{fontSize:13}}>Projects you archive will appear here</div>
        </div>
      )}
      {projects.map(p=>{
        const sc=p.stages.length;
        const pct=sc<=1?0:Math.round((p.currentStage/(sc-1))*100);
        return(
          <div key={p.id} style={{background:C.card,border:'1px solid '+C.border,borderLeft:'4px solid '+C.t3,borderRadius:12,padding:'16px 18px',marginBottom:12,display:'flex',alignItems:'center',gap:16,opacity:0.85}}>
            <div style={{flex:1}}>
              <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:18,color:C.t1,marginBottom:2}}>{p.name}</div>
              <div style={{fontSize:12,color:C.t2,marginBottom:4}}>📍 {p.location||'—'} · 👤 {p.client||'—'}</div>
              <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3}}>
                Archived {p.archivedAt?new Date(p.archivedAt).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—'} · {pct}% complete
              </div>
            </div>
            <div style={{display:'flex',gap:8,flexShrink:0}}>
              <button onClick={()=>setModal({action:'restore',id:p.id,label:'Restore "'+p.name+'"'})} style={{...BS(C.green,'#fff'),padding:'7px 14px',fontSize:13}}>♻️ RESTORE</button>
              <button onClick={()=>setModal({action:'delete',id:p.id,label:'Move "'+p.name+'" to Trash'})} style={{...BS('transparent',C.red),border:'1px solid '+C.red+'60',padding:'7px 12px',fontSize:13}}>🗑</button>
            </div>
          </div>
        );
      })}
      {modal&&<AdminPasswordModal action={modal.action==='restore'?'restore':'delete'} actionLabel={modal.label} user={user} onConfirm={confirm} onCancel={()=>setModal(null)}/>}
    </div>
  );
}

// ── ADMIN TRASH ───────────────────────────────────────────────────────────────
function AdminTrash({projects,user,onRestore,onPermanentDelete}) {
  const [modal,setModal]=useState(null);

  const confirm=()=>{
    if(modal.action==='restore') onRestore(modal.id);
    if(modal.action==='permanent') onPermanentDelete(modal.id);
    setModal(null);
  };

  const daysLeft=(p)=>{
    if(!p.deletedAt) return 60;
    const elapsed=Date.now()-new Date(p.deletedAt).getTime();
    return Math.max(0,60-Math.floor(elapsed/(24*60*60*1000)));
  };

  return(
    <div>
      <Lbl style={{marginBottom:4}}>TRASH ({projects.length})</Lbl>
      <div style={{background:'#FEF3C7',border:'1px solid #FCD34D',borderRadius:10,padding:'12px 16px',marginBottom:20,fontSize:13,color:'#92400E'}}>
        ⚠️ Deleted projects are automatically <strong>permanently removed after 60 days</strong>. Restore within the window to recover.
      </div>
      {projects.length===0&&(
        <div style={{textAlign:'center',padding:'60px 0',color:C.t3}}>
          <div style={{fontSize:48,marginBottom:14}}>🗑️</div>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:20,color:C.t2,marginBottom:6}}>TRASH IS EMPTY</div>
          <div style={{fontSize:13}}>Deleted projects appear here for 60 days before permanent removal</div>
        </div>
      )}
      {projects.map(p=>{
        const days=daysLeft(p);
        const urgent=days<=7;
        return(
          <div key={p.id} style={{background:C.card,border:'1px solid '+C.border,borderLeft:'4px solid '+C.red,borderRadius:12,padding:'16px 18px',marginBottom:12,display:'flex',alignItems:'center',gap:16,opacity:0.8}}>
            <div style={{flex:1}}>
              <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:18,color:C.t1,marginBottom:2}}>{p.name}</div>
              <div style={{fontSize:12,color:C.t2,marginBottom:4}}>📍 {p.location||'—'} · 👤 {p.client||'—'}</div>
              <div style={{display:'flex',alignItems:'center',gap:12}}>
                <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3}}>
                  Deleted {p.deletedAt?new Date(p.deletedAt).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—'}
                </div>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:11,color:urgent?C.red:C.t3,background:(urgent?C.red:C.t3)+'15',borderRadius:5,padding:'2px 8px',letterSpacing:1}}>
                  {days===0?'EXPIRES TODAY':`${days} DAYS LEFT`}
                </div>
              </div>
            </div>
            <div style={{display:'flex',gap:8,flexShrink:0}}>
              <button onClick={()=>setModal({action:'restore',id:p.id,label:'Restore "'+p.name+'"'})} style={{...BS(C.green,'#fff'),padding:'7px 14px',fontSize:13}}>♻️ RESTORE</button>
              <button onClick={()=>setModal({action:'permanent',id:p.id,label:'PERMANENTLY DELETE "'+p.name+'" — this cannot be undone'})} style={{...BS(C.red,'#fff'),padding:'7px 12px',fontSize:13}}>DELETE FOREVER</button>
            </div>
          </div>
        );
      })}
      {modal&&<AdminPasswordModal action={modal.action==='restore'?'restore':'permanent'} actionLabel={modal.label} user={user} onConfirm={confirm} onCancel={()=>setModal(null)}/>}
    </div>
  );
}

function AdminProjectsList({projects,onSelect,onDetail,selProject,profiles,onSave,onSoftDelete,onArchive,onBack,onDelete,user}) {
  const [filterSup,setFilterSup]=useState('');
  const [filterStage,setFilterStage]=useState('');
  const [filterPct,setFilterPct]=useState('');
  const [filterStatus,setFilterStatus]=useState('');

  // Show report/detail view if a project is selected
  if(selProject){
    const p=projects.find(x=>x.id===selProject.id)||selProject;
    return <AdminProjectDetail project={p} profiles={profiles||[]} onSave={onSave} user={user} onArchive={onArchive} onSoftDelete={onSoftDelete} onBack={onBack} onDelete={onDelete?()=>onDelete(p.id):()=>{}}/>;
  }

  // Collect all unique supervisors across all projects
  const allSups=[...new Map(
    projects.flatMap(p=>(p.supervisors||[]).map(s=>([s.name,s])))
  ).values()].sort((a,b)=>a.name.localeCompare(b.name));

  // Collect all unique stage names
  const allStageNames=[...new Set(projects.flatMap(p=>p.stages.map(s=>s.name)))].sort();

  const filtered=projects.filter(p=>{
    const pct=p.stages.length<=1?0:Math.round((p.currentStage/(p.stages.length-1))*100);
    const isDone=p.currentStage>=p.stages.length-1;
    if(filterSup&&!(p.supervisors||[]).some(s=>s.name===filterSup)) return false;
    if(filterStage&&!p.stages.some(s=>s.name===filterStage)) return false;
    if(filterStatus==='active'&&isDone) return false;
    if(filterStatus==='complete'&&!isDone) return false;
    if(filterPct==='0-25'&&pct>25) return false;
    if(filterPct==='25-50'&&(pct<=25||pct>50)) return false;
    if(filterPct==='50-75'&&(pct<=50||pct>75)) return false;
    if(filterPct==='75-99'&&(pct<=75||pct>=100)) return false;
    if(filterPct==='100'&&pct<100) return false;
    return true;
  });

  const hasFilter=filterSup||filterStage||filterPct||filterStatus;
  const selStyle={background:C.surface,border:'1px solid '+C.border,borderRadius:7,padding:'7px 10px',color:C.t1,fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:12,cursor:'pointer',outline:'none'};

  return (
    <div>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:12,flexWrap:'wrap',gap:10}}>
        <Lbl style={{marginBottom:0}}>ALL PROJECTS ({filtered.length}{hasFilter?' — filtered':''})</Lbl>
        {hasFilter&&<button onClick={()=>{setFilterSup('');setFilterStage('');setFilterPct('');setFilterStatus('');}} style={{...BS('transparent',C.red),border:'1px solid '+C.red+'50',padding:'5px 12px',fontSize:12}}>✕ CLEAR ALL FILTERS</button>}
      </div>

      {/* Filter bar */}
      <div style={{display:'flex',flexWrap:'wrap',gap:8,marginBottom:18,background:C.bg,border:'1px solid '+C.border,borderRadius:10,padding:'12px 14px'}}>
        <select value={filterSup} onChange={e=>setFilterSup(e.target.value)} style={selStyle}>
          <option value=''>👷 All Supervisors</option>
          {allSups.map(s=><option key={s.name} value={s.name}>{s.name}</option>)}
        </select>
        <select value={filterStage} onChange={e=>setFilterStage(e.target.value)} style={selStyle}>
          <option value=''>📋 All Stages</option>
          {allStageNames.map(n=><option key={n} value={n}>{n}</option>)}
        </select>
        <select value={filterStatus} onChange={e=>setFilterStatus(e.target.value)} style={selStyle}>
          <option value=''>⚡ All Status</option>
          <option value='active'>In Progress</option>
          <option value='complete'>Completed</option>
        </select>
        <select value={filterPct} onChange={e=>setFilterPct(e.target.value)} style={selStyle}>
          <option value=''>📊 Any Progress</option>
          <option value='0-25'>0 – 25%</option>
          <option value='25-50'>25 – 50%</option>
          <option value='50-75'>50 – 75%</option>
          <option value='75-99'>75 – 99%</option>
          <option value='100'>100% Complete</option>
        </select>
      </div>

      {filtered.length===0&&(
        <div style={{textAlign:'center',padding:'50px 0',color:C.t3}}>
          <div style={{fontSize:36,marginBottom:10}}>🔍</div>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:18,color:C.t2}}>NO PROJECTS MATCH THESE FILTERS</div>
        </div>
      )}

      <div style={{overflowX:'auto'}}>
        <table style={{width:'100%',borderCollapse:'collapse'}}>
          <thead>
            <tr style={{borderBottom:'2px solid '+C.border,background:C.bg}}>
              {['PROJECT','LOCATION','CLIENT','SUPERVISOR(S)','STAGE','PROGRESS','TASKS','UPDATED','ACTIONS'].map(h=>(
                <th key={h} style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.t3,letterSpacing:1,padding:'10px 12px',textAlign:'left',whiteSpace:'nowrap'}}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.map(p=>{
              const sc=p.stages.length;
              const pct=sc<=1?0:Math.round((p.currentStage/(sc-1))*100);
              const done=p.currentStage>=sc-1;
              const tt=p.stages.reduce((a,s)=>a+s.tasks.length,0);
              const td=p.stages.reduce((a,s)=>a+s.tasks.filter(t=>t.status==='done').length,0);
              const sups=(p.supervisors||[]);
              return(
                <tr key={p.id} style={{borderBottom:'1px solid '+C.border,transition:'background 0.1s'}}
                  onMouseEnter={e=>e.currentTarget.style.background=C.bg}
                  onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
                  <td style={{padding:'12px',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:16,color:C.t1}}>{p.name}</td>
                  <td style={{padding:'12px',fontSize:13,color:C.t2,whiteSpace:'nowrap'}}>{p.location||'—'}</td>
                  <td style={{padding:'12px',fontSize:13,color:C.t2,whiteSpace:'nowrap'}}>{p.client||'—'}</td>
                  <td style={{padding:'12px',minWidth:160}}>
                    {sups.length===0
                      ? <span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3}}>—</span>
                      : <div style={{display:'flex',flexDirection:'column',gap:4}}>
                          {sups.map(s=>(
                            <div key={s.id} style={{display:'flex',alignItems:'center',gap:6}}>
                              <div style={{width:20,height:20,borderRadius:'50%',background:C.amber,display:'flex',alignItems:'center',justifyContent:'center',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:9,color:'#fff',flexShrink:0}}>
                                {s.name.split(' ').map(w=>w[0]).slice(0,2).join('')}
                              </div>
                              <div>
                                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:13,color:C.t1,lineHeight:1}}>{s.name}</div>
                                <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.t3}}>{s.role}</div>
                              </div>
                            </div>
                          ))}
                        </div>
                    }
                  </td>
                  <td style={{padding:'12px',fontSize:12,color:C.amber,whiteSpace:'nowrap',fontFamily:"'JetBrains Mono',monospace"}}>{p.currentStage+1}/{sc}</td>
                  <td style={{padding:'12px',minWidth:130}}>
                    <div style={{display:'flex',alignItems:'center',gap:8}}>
                      <div style={{flex:1,background:C.border,borderRadius:4,height:6}}>
                        <div style={{width:pct+'%',height:'100%',background:'linear-gradient(90deg,'+C.amber+','+C.amberD+')',borderRadius:4}}/>
                      </div>
                      <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:13,color:done?C.green:C.amber,minWidth:36}}>{pct}%</span>
                    </div>
                  </td>
                  <td style={{padding:'12px',fontFamily:"'JetBrains Mono',monospace",fontSize:11,color:C.t2,whiteSpace:'nowrap'}}>{td}/{tt}</td>
                  <td style={{padding:'12px',fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3,whiteSpace:'nowrap'}}>{p._updated?new Date(p._updated).toLocaleDateString('en-GB',{day:'2-digit',month:'short'}):'—'}</td>
                  <td style={{padding:'8px 12px',whiteSpace:'nowrap'}}>
                    <div style={{display:'flex',gap:6}}>
                      <button onClick={()=>onSelect(p)} style={{...BS(C.amber),padding:'5px 12px',fontSize:11,letterSpacing:0.5}}>OPEN</button>
                      <button onClick={()=>onDetail&&onDetail(p)} style={{...BS('transparent',C.t2),padding:'5px 10px',fontSize:11,border:'1px solid '+C.border}}>REPORT</button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function AdminProjectDetail({project:p,profiles=[],onSave,onBack,onDelete,onArchive,onSoftDelete,user}) {
  const sc=p.stages.length;
  const pct=sc<=1?0:Math.round((p.currentStage/(sc-1))*100);
  const tt=p.stages.reduce((a,s)=>a+s.tasks.length,0);
  const td=p.stages.reduce((a,s)=>a+s.tasks.filter(t=>t.status==='done').length,0);
  const [showPasswordModal,setShowPasswordModal]=useState(null);
  const [editingName,setEditingName]=useState(false);
  const [nameVal,setNameVal]=useState(p.name); // {action, onConfirm}
  const [showAssign,setShowAssign]=useState(false);

  const assignedIds=p.assignedUserIds||[];
  const assignedProfiles=profiles.filter(pr=>assignedIds.includes(pr.id));
  const unassignedProfiles=profiles.filter(pr=>!assignedIds.includes(pr.id)&&pr.role==='supervisor');

  const assignUser=(userId)=>{
    const updated={...p,assignedUserIds:[...assignedIds,userId]};
    onSave(updated);
  };
  const unassignUser=(userId)=>{
    const updated={...p,assignedUserIds:assignedIds.filter(id=>id!==userId)};
    onSave(updated);
  };

  return (
    <div>
      <div className="no-print" style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:20}}>
        <button onClick={onBack} style={{...BS('transparent',C.amber),border:'1px solid '+C.border,padding:'7px 14px',fontSize:13}}>‹ BACK</button>
        <div style={{display:'flex',gap:8}}>
          <button onClick={()=>window.print()} style={{...BS(C.blue,'#000'),padding:'7px 14px',fontSize:13}}>🖨 PRINT REPORT</button>
          <button onClick={()=>setShowPasswordModal({action:'archive',label:'Archive "'+p.name+'"',onConfirm:()=>{onArchive(p.id);onBack();}})} style={{...BS('transparent',C.t2),border:'1px solid '+C.border,padding:'7px 12px',fontSize:13}}>📦 ARCHIVE</button>
          <button onClick={()=>setShowPasswordModal({action:'delete',label:'Move "'+p.name+'" to Trash',onConfirm:()=>{onSoftDelete(p.id);onBack();}})} style={{...BS('transparent',C.red),border:'1px solid '+C.red+'60',padding:'7px 12px',fontSize:13}}>🗑 DELETE</button>
        </div>
      </div>
      <div className="print-area">
        {/* Header */}
        <div style={{background:C.card,border:'1px solid '+C.border,borderRadius:12,padding:'20px 22px',marginBottom:20}}>
          <div style={{marginBottom:8}}>
            {editingName?(
              <div style={{display:'flex',alignItems:'center',gap:8}}>
                <input autoFocus value={nameVal} onChange={e=>setNameVal(e.target.value)}
                  onKeyDown={e=>{if(e.key==='Enter'){onSave({...p,name:nameVal.trim()||p.name});setEditingName(false);}if(e.key==='Escape'){setNameVal(p.name);setEditingName(false);}}}
                  style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:24,border:'2px solid '+C.amber,borderRadius:8,background:'#fffbeb',color:C.t1,outline:'none',flex:1,padding:'6px 10px'}}/>
                <button onClick={()=>{onSave({...p,name:nameVal.trim()||p.name});setEditingName(false);}} style={{background:C.green,border:'none',borderRadius:8,padding:'8px 14px',color:'#fff',cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:13,flexShrink:0}}>SAVE</button>
                <button onClick={()=>{setNameVal(p.name);setEditingName(false);}} style={{background:C.border,border:'none',borderRadius:8,padding:'8px 12px',color:C.t2,cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:13,flexShrink:0}}>✕</button>
              </div>
            ):(
              <div style={{display:'flex',alignItems:'center',gap:10}}>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:28,color:C.t1,flex:1}}>{p.name}</div>
                <button onClick={()=>{setNameVal(p.name);setEditingName(true);}} style={{background:C.amber+'20',border:'1px solid '+C.amber,borderRadius:8,padding:'5px 12px',cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:12,color:C.amber,flexShrink:0,whiteSpace:'nowrap'}}>✏️ RENAME</button>
              </div>
            )}
          </div>
          <div style={{display:'flex',flexWrap:'wrap',gap:'8px 24px',color:C.t2,fontSize:13,marginBottom:16}}>
            <span>📍 {p.location||'—'}</span>
            <span>👤 {p.client||'—'}</span>
            {p.startDate&&<span>📅 Started {new Date(p.startDate).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}</span>}
            <span>🗓 Report: {new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}</span>
          </div>
          <div style={{display:'flex',gap:16,flexWrap:'wrap',marginBottom:14}}>
            {[['OVERALL PROGRESS',pct+'%',pct>=100?C.green:C.amber],['STAGE',p.currentStage+1+' of '+sc,C.blue],['TASKS DONE',td+' / '+tt,C.green]].map(([l,v,col])=>(
              <div key={l} style={{background:C.bg,borderRadius:8,padding:'10px 16px',textAlign:'center'}}>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:22,color:col,lineHeight:1}}>{v}</div>
                <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.t3,marginTop:4}}>{l}</div>
              </div>
            ))}
          </div>
          <div style={{background:C.border,borderRadius:4,height:8}}>
            <div style={{width:pct+'%',height:'100%',background:'linear-gradient(90deg,'+C.amber+','+C.green+')',borderRadius:4,transition:'width 0.5s'}}/>
          </div>
        </div>

        {/* Assigned Users — who can see this project */}
        <div className="no-print" style={{background:C.card,border:'1px solid '+C.amber,borderRadius:12,padding:'16px 20px',marginBottom:20}}>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:12}}>
            <div>
              <Lbl style={{marginBottom:2}}>PORTAL ACCESS — ASSIGNED SUPERVISORS</Lbl>
              <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3}}>Only these users can see this project in their Supervisor Portal</div>
            </div>
            <button onClick={()=>setShowAssign(!showAssign)} style={{...BS(C.amber),padding:'6px 14px',fontSize:12}}>{showAssign?'DONE':'+ ASSIGN'}</button>
          </div>

          {/* Currently assigned */}
          {assignedProfiles.length===0&&!showAssign&&(
            <div style={{color:C.t3,fontSize:13,fontStyle:'italic'}}>No supervisors assigned yet — this project is hidden from all supervisor portals</div>
          )}
          <div style={{display:'flex',flexWrap:'wrap',gap:8,marginBottom:showAssign?14:0}}>
            {assignedProfiles.map(pr=>{
              const ini=(pr.full_name||pr.email||'?').split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();
              return(
                <div key={pr.id} style={{display:'flex',alignItems:'center',gap:8,background:C.green+'15',border:'1px solid '+C.green+'50',borderRadius:8,padding:'8px 12px'}}>
                  <div style={{width:30,height:30,borderRadius:'50%',background:C.green,display:'flex',alignItems:'center',justifyContent:'center',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:12,color:'#fff',flexShrink:0}}>{ini}</div>
                  <div>
                    <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:14,color:C.t1}}>{pr.full_name||pr.email}</div>
                    <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.t3}}>{pr.email}</div>
                  </div>
                  <button onClick={()=>unassignUser(pr.id)} title="Remove access" style={{background:'transparent',border:'none',color:C.red,cursor:'pointer',fontSize:18,lineHeight:1,padding:'0 2px',marginLeft:4}}>×</button>
                </div>
              );
            })}
          </div>

          {/* Assign dropdown */}
          {showAssign&&(
            <div>
              <Lbl style={{marginBottom:8}}>ADD SUPERVISOR ACCESS</Lbl>
              {unassignedProfiles.length===0
                ? <div style={{color:C.t3,fontSize:13,fontStyle:'italic'}}>All supervisors are already assigned, or no supervisors have signed up yet</div>
                : <div style={{display:'flex',flexWrap:'wrap',gap:8}}>
                    {unassignedProfiles.map(pr=>{
                      const ini=(pr.full_name||pr.email||'?').split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();
                      return(
                        <button key={pr.id} onClick={()=>assignUser(pr.id)} style={{display:'flex',alignItems:'center',gap:8,background:C.surface,border:'1px solid '+C.border,borderRadius:8,padding:'8px 12px',cursor:'pointer'}}>
                          <div style={{width:28,height:28,borderRadius:'50%',background:C.amber,display:'flex',alignItems:'center',justifyContent:'center',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:11,color:'#fff',flexShrink:0}}>{ini}</div>
                          <div style={{textAlign:'left'}}>
                            <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:13,color:C.t1}}>{pr.full_name||pr.email}</div>
                            <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.t3}}>Click to grant access</div>
                          </div>
                        </button>
                      );
                    })}
                  </div>
              }
            </div>
          )}
        </div>

        {/* Team */}
        {p.supervisors?.length>0&&(
          <div style={{background:C.card,border:'1px solid '+C.border,borderRadius:12,padding:'16px 20px',marginBottom:20}}>
            <Lbl style={{marginBottom:12}}>PROJECT TEAM CONTACTS</Lbl>
            <div style={{display:'flex',flexWrap:'wrap',gap:10}}>
              {p.supervisors.map(s=>{const rc=ROLE_C[s.role]||C.t3;const ini=s.name.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();return(
                <div key={s.id} style={{background:C.bg,border:'1px solid '+C.border,borderRadius:8,padding:'10px 14px',display:'flex',alignItems:'center',gap:10}}>
                  <div style={{width:34,height:34,borderRadius:'50%',background:rc+'20',border:'2px solid '+rc,display:'flex',alignItems:'center',justifyContent:'center',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:13,color:rc,flexShrink:0}}>{ini}</div>
                  <div><div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:15}}>{s.name}</div><div style={{fontSize:11,color:rc}}>{s.role}</div></div>
                </div>
              );})}
            </div>
          </div>
        )}

        {/* Stages */}
        <Lbl style={{marginBottom:12}}>STAGE-BY-STAGE BREAKDOWN</Lbl>
        {p.stages.map((s,i)=>{
          const isA=i===p.currentStage,isD=s.status==='complete';
          const stageCol=getStagColor(i); const col=isD?C.green:isA?stageCol:C.t3;
          const stDone=s.tasks.filter(t=>t.status==='done').length;
          const stTodo=s.tasks.filter(t=>t.status==='todo').length;
          const stDoing=s.tasks.filter(t=>t.status==='doing').length;
          return(
            <div key={s.id} className="print-stage" style={{background:C.card,border:'1px solid '+(isA?getStagColor(i):C.border),borderLeft:'4px solid '+col,borderRadius:10,padding:'16px 18px',marginBottom:12}}>
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:10}}>
                <div style={{display:'flex',alignItems:'center',gap:10}}>
                  <div style={{width:28,height:28,borderRadius:'50%',background:isD?C.green:isA?getStagColor(i):C.border,display:'flex',alignItems:'center',justifyContent:'center',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:12,color:isD||isA?'#000':C.t3,flexShrink:0}}>{isD?"✓":i+1}</div>
                  <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:18,color:col}}>{s.name}</div>
                  {isA&&<span style={{background:C.amber,borderRadius:4,padding:'2px 8px',fontFamily:"'Barlow Condensed',sans-serif",fontSize:10,fontWeight:700,color:'#000'}}>ACTIVE</span>}
                  {isD&&<span style={{background:C.green,borderRadius:4,padding:'2px 8px',fontFamily:"'Barlow Condensed',sans-serif",fontSize:10,fontWeight:700,color:'#000'}}>DONE</span>}
                </div>
                {s.tasks.length>0&&(
                  <div style={{display:'flex',gap:10,flexShrink:0}}>
                    {[[stDone,'DONE',C.green],[stDoing,'ACTIVE',C.amber],[stTodo,'PLANNED',C.blue]].map(([n,l,c])=>n>0?(
                      <div key={l} style={{textAlign:'center'}}>
                        <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:18,color:c,lineHeight:1}}>{n}</div>
                        <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:8,color:C.t3}}>{l}</div>
                      </div>
                    ):null)}
                  </div>
                )}
              </div>
              {s.achievements&&<div style={{fontSize:13,color:C.green,marginBottom:6}}>✅ {s.achievements}</div>}
              {s.notes&&<div style={{fontSize:13,color:C.t2,marginBottom:6}}>🔨 {s.notes}</div>}
              {s.nextSteps&&<div style={{fontSize:13,color:C.blue,marginBottom:6}}>⏭ {s.nextSteps}</div>}
              {s.tasks.length>0&&(
                <div style={{marginTop:10,display:'flex',flexWrap:'wrap',gap:6}}>
                  {s.tasks.map(t=>(
                    <div key={t.id} style={{background:C.bg,borderRadius:6,padding:'4px 10px',fontSize:12,color:t.status==='done'?C.green:t.status==='doing'?C.amber:C.t2,border:'1px solid '+C.border,display:'flex',alignItems:'center',gap:5}}>
                      <span>{t.status==='done'?"✓":t.status==='doing'?"⏳":"○"}</span>{t.title}
                    </div>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>
      {showPasswordModal&&<AdminPasswordModal action={showPasswordModal.action} actionLabel={showPasswordModal.label} user={user||{id:'local',email:'admin@local'}} onConfirm={()=>{showPasswordModal.onConfirm();setShowPasswordModal(null);}} onCancel={()=>setShowPasswordModal(null)}/>}
    </div>
  );
}

function AdminReports({projects}) {
  const [sel,setSel]=useState(null);
  const p=sel?projects.find(x=>x.id===sel):null;
  return (
    <div>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>
        <Lbl style={{marginBottom:0}}>PROJECT REPORTS</Lbl>
        {p&&<div style={{display:'flex',gap:8}}>
          <button onClick={()=>setSel(null)} style={{...BS('transparent',C.t2),border:'1px solid '+C.border,padding:'6px 12px',fontSize:12}}>← ALL PROJECTS</button>
          <button onClick={()=>window.print()} style={{...BS(C.blue,'#000'),padding:'6px 14px',fontSize:12}}>🖨 PRINT</button>
        </div>}
      </div>
      {!p&&(
        <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(280px,1fr))',gap:12}}>
          {projects.map(proj=>{
            const sc=proj.stages.length;
            const pct=sc<=1?0:Math.round((proj.currentStage/(sc-1))*100);
            const done=proj.currentStage>=sc-1;
            const tt=proj.stages.reduce((a,s)=>a+s.tasks.length,0);
            const td=proj.stages.reduce((a,s)=>a+s.tasks.filter(t=>t.status==='done').length,0);
            return(
              <button key={proj.id} onClick={()=>setSel(proj.id)} style={{background:C.card,border:'1px solid '+C.border,borderLeft:'4px solid '+(done?C.green:C.amber),borderRadius:10,padding:'16px',textAlign:'left',cursor:'pointer',width:'100%'}}>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:18,color:C.t1,marginBottom:4}}>{proj.name}</div>
                <div style={{fontSize:12,color:C.t2,marginBottom:10}}>📍 {proj.location||'—'} · {proj.client||'—'}</div>
                <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:4}}>
                  <div style={{flex:1,background:C.border,borderRadius:4,height:5}}><div style={{width:pct+'%',height:'100%',background:'linear-gradient(90deg,'+C.amber+','+C.amberD+')',borderRadius:4}}/></div>
                  <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:14,color:done?C.green:C.amber}}>{pct}%</span>
                </div>
                <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.t3}}>STAGE {proj.currentStage+1}/{sc} · {td}/{tt} TASKS · {proj.supervisors?.length||0} TEAM</div>
              </button>
            );
          })}
        </div>
      )}
      {p&&<AdminProjectDetail project={p} onBack={()=>setSel(null)} onDelete={()=>{}}/>}
    </div>
  );
}

// ── ADMIN TEMPLATES ──────────────────────────────────────────────────────────
function AdminTemplates({templates,loading,onSave,onDelete}) {
  const [editing,setEditing]=useState(null); // null=list, 'new'=new, id=editing

  if(loading) return <div style={{textAlign:'center',padding:'50px 0',color:C.t3}}>Loading templates…</div>;
  if(editing) return <TemplateEditor template={editing==='new'?null:templates.find(t=>t.id===editing)} onBack={()=>setEditing(null)} onSave={async t=>{await onSave(t);setEditing(null);}}/>;

  return (
    <div>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:20}}>
        <div>
          <Lbl style={{marginBottom:2}}>PROJECT TEMPLATES</Lbl>
          <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3}}>Pre-fill stages and tasks for new projects</div>
        </div>
        <button onClick={()=>setEditing('new')} style={{...BS(C.amber),padding:'9px 16px'}}>+ NEW TEMPLATE</button>
      </div>
      {templates.length===0&&(
        <div style={{textAlign:'center',padding:'60px 0',color:C.t3}}>
          <div style={{fontSize:48,marginBottom:14}}>📐</div>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:22,color:C.t2,marginBottom:8}}>NO TEMPLATES YET</div>
          <div style={{fontSize:14}}>Create a template to pre-fill stages and tasks when supervisors start a new project</div>
        </div>
      )}
      <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(280px,1fr))',gap:14}}>
        {templates.map(t=>(
          <div key={t.id} style={{background:C.card,border:'1px solid '+C.border,borderLeft:'4px solid '+C.amber,borderRadius:12,padding:'16px 18px'}}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',marginBottom:8}}>
              <div>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:19,color:C.t1,marginBottom:3}}>{t.name}</div>
                {t.description&&<div style={{fontSize:12,color:C.t2}}>{t.description}</div>}
              </div>
              <div style={{display:'flex',gap:6,flexShrink:0}}>
                <button onClick={()=>setEditing(t.id)} style={{background:'transparent',border:'none',cursor:'pointer',fontSize:14,padding:'2px 4px'}}>✏️</button>
                <button onClick={()=>onDelete(t.id)} style={{background:'transparent',border:'none',color:C.t3,cursor:'pointer',fontSize:18,lineHeight:1,padding:0}}>×</button>
              </div>
            </div>
            <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3,marginBottom:10}}>
              {t.stages?.length||0} STAGES · {t.stages?.reduce((a,s)=>a+(s.tasks?.length||0),0)||0} TASKS
            </div>
            <div style={{display:'flex',flexWrap:'wrap',gap:5}}>
              {(t.stages||[]).slice(0,5).map(s=>(
                <div key={s.id} style={{background:C.bg,border:'1px solid '+C.border,borderRadius:5,padding:'3px 8px',fontSize:11,color:C.t2}}>{s.name}</div>
              ))}
              {(t.stages||[]).length>5&&<div style={{background:C.bg,border:'1px solid '+C.border,borderRadius:5,padding:'3px 8px',fontSize:11,color:C.t3}}>+{t.stages.length-5} more</div>}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function TemplateEditor({template,onBack,onSave}) {
  const isNew=!template;
  const [name,setName]=useState(template?.name||'');
  const [desc,setDesc]=useState(template?.description||'');
  const [stages,setStages]=useState(template?.stages||[]);
  const [openStage,setOpenStage]=useState(null);
  const [newStageName,setNewStageName]=useState('');
  const [saving,setSaving]=useState(false);

  const addStage=()=>{
    if(!newStageName.trim()) return;
    const s={id:uid(),name:newStageName.trim(),tasks:[]};
    setStages(prev=>[...prev,s]);
    setNewStageName('');
    setOpenStage(s.id);
  };
  const delStage=id=>setStages(prev=>prev.filter(s=>s.id!==id));
  const renameStage=(id,n)=>setStages(prev=>prev.map(s=>s.id===id?{...s,name:n}:s));
  const moveStage=(i,dir)=>{const j=i+dir;if(j<0||j>=stages.length)return;const ns=[...stages];[ns[i],ns[j]]=[ns[j],ns[i]];setStages(ns);};

  const addTask=(sid,title,priority)=>{
    if(!title.trim()) return;
    const t={id:uid(),title:title.trim(),priority:priority||'medium',notes:''};
    setStages(prev=>prev.map(s=>s.id===sid?{...s,tasks:[...s.tasks,t]}:s));
  };
  const delTask=(sid,tid)=>setStages(prev=>prev.map(s=>s.id===sid?{...s,tasks:s.tasks.filter(t=>t.id!==tid)}:s));
  const moveTask=(sid,tid,dir)=>{
    setStages(prev=>prev.map(s=>{
      if(s.id!==sid) return s;
      const tasks=[...s.tasks];
      const i=tasks.findIndex(t=>t.id===tid);
      const j=i+dir;
      if(j<0||j>=tasks.length) return s;
      [tasks[i],tasks[j]]=[tasks[j],tasks[i]];
      return {...s,tasks};
    }));
  };
  const updateTask=(sid,tid,field,val)=>setStages(prev=>prev.map(s=>s.id===sid?{...s,tasks:s.tasks.map(t=>t.id===tid?{...t,[field]:val}:t)}:s));

  const handleSave=async()=>{
    if(!name.trim()) return;
    setSaving(true);
    await onSave({id:template?.id||uid(),name:name.trim(),description:desc.trim(),stages,created_at:template?.created_at||new Date().toISOString()});
    setSaving(false);
  };

  return (
    <div>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:20}}>
        <div style={{display:'flex',alignItems:'center',gap:12}}>
          <button onClick={onBack} style={{...BS('transparent',C.amber),border:'1px solid '+C.border,padding:'7px 12px',fontSize:13}}>‹ BACK</button>
          <Lbl style={{marginBottom:0}}>{isNew?'NEW TEMPLATE':'EDIT TEMPLATE'}</Lbl>
        </div>
        <button onClick={handleSave} disabled={saving||!name.trim()} style={{...BS(C.amber),padding:'9px 20px',opacity:saving?0.7:1}}>{saving?'SAVING…':'SAVE TEMPLATE'}</button>
      </div>

      {/* Template info */}
      <div style={{background:C.card,border:'1px solid '+C.border,borderRadius:12,padding:'18px',marginBottom:20}}>
        <div style={{marginBottom:14}}>
          <label style={LS}>TEMPLATE NAME</label>
          <input value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Residential Build, Commercial Fitout…" style={IS()}/>
        </div>
        <div>
          <label style={LS}>DESCRIPTION (optional)</label>
          <input value={desc} onChange={e=>setDesc(e.target.value)} placeholder="Brief description of when to use this template" style={IS()}/>
        </div>
      </div>

      {/* Stages */}
      <Lbl style={{marginBottom:12}}>{stages.length} STAGE{stages.length!==1?'S':''} — CLICK A STAGE TO MANAGE ITS TASKS</Lbl>
      {stages.map((s,si)=>(
        <div key={s.id} style={{background:C.card,border:'1px solid '+(openStage===s.id?C.amber:C.border),borderRadius:10,marginBottom:10,overflow:'hidden'}}>
          {/* Stage header */}
          <div style={{display:'flex',alignItems:'center',gap:8,padding:'12px 14px',cursor:'pointer'}} onClick={()=>setOpenStage(openStage===s.id?null:s.id)}>
            <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:11,color:C.t3,width:20,flexShrink:0}}>{si+1}</div>
            <input
              value={s.name}
              onChange={e=>{e.stopPropagation();renameStage(s.id,e.target.value);}}
              onClick={e=>e.stopPropagation()}
              style={IS({flex:1,padding:'7px 10px',background:'transparent',border:'1px solid '+C.border})}
            />
            <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3,flexShrink:0}}>{s.tasks?.length||0} tasks</div>
            <button onClick={e=>{e.stopPropagation();moveStage(si,-1);}} disabled={si===0} style={{background:'transparent',border:'1px solid '+C.border,borderRadius:5,cursor:si===0?'default':'pointer',width:26,height:26,color:si===0?C.border:C.t2,display:'flex',alignItems:'center',justifyContent:'center',fontSize:10,flexShrink:0}}>▲</button>
            <button onClick={e=>{e.stopPropagation();moveStage(si,1);}} disabled={si>=stages.length-1} style={{background:'transparent',border:'1px solid '+C.border,borderRadius:5,cursor:si>=stages.length-1?'default':'pointer',width:26,height:26,color:si>=stages.length-1?C.border:C.t2,display:'flex',alignItems:'center',justifyContent:'center',fontSize:10,flexShrink:0}}>▼</button>
            <button onClick={e=>{e.stopPropagation();delStage(s.id);}} style={{background:'transparent',border:'none',color:C.red,cursor:'pointer',fontSize:20,lineHeight:1,padding:'0 2px',flexShrink:0}}>×</button>
            <span style={{color:C.t3,fontSize:13,flexShrink:0}}>{openStage===s.id?"▴":"▾"}</span>
          </div>
          {/* Task list */}
          {openStage===s.id&&(
            <div style={{borderTop:'1px solid '+C.border,padding:'14px'}}>
              {(s.tasks||[]).length===0&&<div style={{color:C.t3,fontSize:13,fontStyle:'italic',marginBottom:12}}>No tasks yet — add some below</div>}
              {(s.tasks||[]).map((t,ti)=>(
                <div key={t.id} style={{background:C.bg,border:'1px solid '+C.border,borderLeft:'3px solid '+PC[t.priority],borderRadius:7,padding:'9px 12px',marginBottom:7,display:'flex',alignItems:'center',gap:8}}>
                  <div style={{flex:1,minWidth:0}}>
                    <input
                      value={t.title}
                      onChange={e=>updateTask(s.id,t.id,'title',e.target.value)}
                      style={{width:'100%',background:'transparent',border:'none',color:C.t1,fontFamily:"'Barlow',sans-serif",fontSize:13,outline:'none',marginBottom:2}}
                    />
                    <div style={{display:'flex',gap:6}}>
                      {['high','medium','low'].map(pr=>(
                        <button key={pr} onClick={()=>updateTask(s.id,t.id,'priority',pr)} style={{padding:'2px 8px',borderRadius:12,border:'1px solid '+PC[pr],background:t.priority===pr?PC[pr]+'25':'transparent',color:PC[pr],cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:9,letterSpacing:1}}>{pr.toUpperCase()}</button>
                      ))}
                    </div>
                  </div>
                  <button onClick={()=>moveTask(s.id,t.id,-1)} disabled={ti===0} style={{background:'transparent',border:'1px solid '+C.border,borderRadius:5,cursor:ti===0?'default':'pointer',width:24,height:24,color:ti===0?C.border:C.t2,display:'flex',alignItems:'center',justifyContent:'center',fontSize:10,flexShrink:0}}>▲</button>
                  <button onClick={()=>moveTask(s.id,t.id,1)} disabled={ti>=(s.tasks.length-1)} style={{background:'transparent',border:'1px solid '+C.border,borderRadius:5,cursor:ti>=(s.tasks.length-1)?'default':'pointer',width:24,height:24,color:ti>=(s.tasks.length-1)?C.border:C.t2,display:'flex',alignItems:'center',justifyContent:'center',fontSize:10,flexShrink:0}}>▼</button>
                  <button onClick={()=>delTask(s.id,t.id)} style={{background:'transparent',border:'none',color:C.t3,cursor:'pointer',fontSize:18,lineHeight:1,padding:0,flexShrink:0}}>×</button>
                </div>
              ))}
              <AddTaskRow onAdd={(title,pri)=>addTask(s.id,title,pri)}/>
            </div>
          )}
        </div>
      ))}

      {/* Add stage */}
      <div style={{background:C.surface,border:'1px dashed '+C.amber+'60',borderRadius:10,padding:'14px',marginTop:8}}>
        <label style={{...LS,marginBottom:8}}>ADD STAGE</label>
        <div style={{display:'flex',gap:8}}>
          <input value={newStageName} onChange={e=>setNewStageName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&addStage()} placeholder="e.g. Foundation Works, Interior Finishing…" style={IS({flex:1})}/>
          <button onClick={addStage} style={{...BS(C.amber),padding:'10px 16px'}}>ADD</button>
        </div>
      </div>
    </div>
  );
}

function AddTaskRow({onAdd}) {
  const [title,setTitle]=useState('');
  const [pri,setPri]=useState('medium');
  const submit=()=>{if(!title.trim())return;onAdd(title,pri);setTitle('');};
  return(
    <div style={{background:C.surface,border:'1px dashed '+C.border,borderRadius:7,padding:'10px 12px',marginTop:8}}>
      <div style={{display:'flex',gap:8,marginBottom:8}}>
        <input value={title} onChange={e=>setTitle(e.target.value)} onKeyDown={e=>e.key==='Enter'&&submit()} placeholder="Add a task…" style={IS({flex:1,padding:'7px 10px'})}/>
        <button onClick={submit} style={{...BS(C.amber),padding:'7px 14px',fontSize:13}}>ADD</button>
      </div>
      <div style={{display:'flex',gap:6}}>
        {['high','medium','low'].map(pr=>(
          <button key={pr} onClick={()=>setPri(pr)} style={{padding:'2px 10px',borderRadius:12,border:'1px solid '+PC[pr],background:pri===pr?PC[pr]+'25':'transparent',color:PC[pr],cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:9,letterSpacing:1}}>{pr.toUpperCase()}</button>
        ))}
      </div>
    </div>
  );
}

function AdminUsers({profiles,loading,currentUserId,onRoleChange}) {
  const [showInvite,setShowInvite]=useState(false);
  const [inviteName,setInviteName]=useState('');
  const [inviteEmail,setInviteEmail]=useState('');
  const [copied,setCopied]=useState(false);
  const siteUrl=window.location.origin+window.location.pathname;

  const inviteMsg=`Hi ${inviteName||'there'},\n\nYou've been invited to Paciffic Homes — our construction project management portal.\n\n📱 Open this link to create your account:\n${siteUrl}\n\n1. Click "No account? Sign up"\n2. Enter your name, email and choose a password\n3. Check your email and click the confirmation link\n4. You're in!\n\nLet me know if you need any help.`;

  const copyInvite=()=>{
    navigator.clipboard.writeText(inviteMsg).then(()=>{ setCopied(true); setTimeout(()=>setCopied(false),2500); });
  };

  const whatsapp=()=>{
    window.open('https://wa.me/?text='+encodeURIComponent(inviteMsg),'_blank');
  };

  const mailto=()=>{
    window.open('mailto:'+inviteEmail+'?subject='+encodeURIComponent('You\'re invited to Paciffic Homes')+'&body='+encodeURIComponent(inviteMsg),'_blank');
  };

  if(loading) return <div style={{textAlign:'center',padding:'50px 0',color:C.t3}}>Loading users…</div>;

  return (
    <div>

      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:6}}>
        <Lbl style={{marginBottom:0}}>USER MANAGEMENT</Lbl>
        <button onClick={()=>setShowInvite(!showInvite)} style={{...BS(C.amber),padding:'8px 16px',fontSize:13}}>+ INVITE SUPERVISOR</button>
      </div>
      <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontSize:13,color:C.t3,marginBottom:20}}>Invite supervisors to sign up, then manage their roles below.</div>

      {/* Invite panel */}
      {showInvite&&(
        <div style={{background:C.card,border:'1px solid '+C.amber,borderRadius:12,padding:'20px',marginBottom:24}}>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:18,letterSpacing:1,marginBottom:16}}>INVITE A SUPERVISOR</div>
          <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:12,marginBottom:16}}>
            <div>
              <label style={LS}>THEIR NAME</label>
              <input value={inviteName} onChange={e=>setInviteName(e.target.value)} placeholder="e.g. James O'Brien" style={IS()}/>
            </div>
            <div>
              <label style={LS}>THEIR EMAIL (for mail)</label>
              <input value={inviteEmail} onChange={e=>setInviteEmail(e.target.value)} type="email" placeholder="james@company.com" style={IS()}/>
            </div>
          </div>

          {/* Preview */}
          <div style={{background:C.bg,border:'1px solid '+C.border,borderRadius:8,padding:'14px',marginBottom:14,fontFamily:"'Barlow',sans-serif",fontSize:13,color:C.t2,lineHeight:1.7,whiteSpace:'pre-wrap'}}>{inviteMsg}</div>

          {/* App URL quick copy */}
          <div style={{background:C.surface,border:'1px solid '+C.border,borderRadius:8,padding:'10px 14px',marginBottom:14,display:'flex',alignItems:'center',gap:10}}>
            <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:12,color:C.amber,flex:1,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{siteUrl}</div>
            <button onClick={()=>{navigator.clipboard.writeText(siteUrl);}} style={{...BS(C.border,C.t2),padding:'5px 12px',fontSize:11,border:'1px solid '+C.border,flexShrink:0}}>COPY LINK</button>
          </div>

          <div style={{display:'flex',gap:10,flexWrap:'wrap'}}>
            <button onClick={whatsapp} style={{...BS('#25D366','#fff'),flex:1,padding:'11px',fontSize:14,display:'flex',alignItems:'center',justifyContent:'center',gap:8,minWidth:120}}>
              <span style={{fontSize:18}}>💬</span> SEND VIA WHATSAPP
            </button>
            <button onClick={mailto} disabled={!inviteEmail} style={{...BS(C.blue,'#000'),flex:1,padding:'11px',fontSize:14,display:'flex',alignItems:'center',justifyContent:'center',gap:8,minWidth:120,opacity:inviteEmail?1:0.5}}>
              <span style={{fontSize:18}}>✉️</span> SEND VIA EMAIL
            </button>
            <button onClick={copyInvite} style={{...BS(copied?C.green:C.surface,copied?'#000':C.t1),flex:1,padding:'11px',fontSize:14,border:'1px solid '+C.border,display:'flex',alignItems:'center',justifyContent:'center',gap:8,minWidth:120}}>
              <span style={{fontSize:18}}>{copied?"✓":"📋"}</span> {copied?'COPIED!':'COPY MESSAGE'}
            </button>
          </div>
          <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3,marginTop:12,textAlign:'center'}}>
            Once they sign up, they'll appear in the list below. You can promote them to Admin anytime.
          </div>
        </div>
      )}

      {/* Users list */}
      <div style={{background:C.card,border:'1px solid '+C.border,borderRadius:12,overflow:'hidden'}}>
        {profiles.length===0&&<div style={{textAlign:'center',padding:'40px',color:C.t3}}>
          <div style={{fontSize:40,marginBottom:12}}>👷</div>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:18,color:C.t2,marginBottom:6}}>NO USERS YET</div>
          <div style={{fontSize:13}}>Invite your supervisors above — they'll appear here once they sign up</div>
        </div>}
        {profiles.map((prof,i)=>{
          const isAdmin=prof.role==='admin';
          const col=isAdmin?C.amber:C.blue;
          const initials=(prof.full_name||prof.email||'?').split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();
          return(
            <div key={prof.id} style={{padding:'14px 18px',borderBottom:i<profiles.length-1?'1px solid '+C.border:'none',display:'flex',alignItems:'center',gap:14}}>
              <div style={{width:42,height:42,borderRadius:'50%',background:col+'25',border:'2px solid '+col,display:'flex',alignItems:'center',justifyContent:'center',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:15,color:col,flexShrink:0}}>
                {initials}
              </div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:16,color:C.t1}}>{prof.full_name||'—'}</div>
                <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:11,color:C.t2,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{prof.email}</div>
                <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.t3,marginTop:2}}>
                  Joined {new Date(prof.created_at).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}
                </div>
              </div>
              <div style={{flexShrink:0,display:'flex',alignItems:'center',gap:10}}>
                <div style={{background:col+'20',border:'1px solid '+col+'60',borderRadius:6,padding:'4px 10px',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:11,color:col,letterSpacing:1}}>
                  {isAdmin?'ADMIN':'SUPERVISOR'}
                </div>
                {prof.id===currentUserId ? (
                  <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontSize:10,color:C.t3}}>YOU</div>
                ) : (
                  <select value={prof.role} onChange={e=>onRoleChange(prof.id,e.target.value)}
                    style={{background:C.bg,border:'1px solid '+C.border,borderRadius:6,padding:'6px 10px',color:C.t1,fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:11,cursor:'pointer',outline:'none'}}>
                    <option value="supervisor">MAKE SUPERVISOR</option>
                    <option value="admin">MAKE ADMIN</option>
                  </select>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ── SUPERVISOR APP ────────────────────────────────────────────────────────────
function SupervisorApp({user,profile,profiles,projects,onSave,onCreate,onDelete,onArchive,onSoftDelete,onSignOut,onSwitchView,viewAs}) {
  const [screen,setScreen]=useState('home');
  const [activeId,setActiveId]=useState(null);
  const [templates,setTemplates]=useState([]);
  const [activeTab,setActiveTab]=useState('projects');

  const myProjects=projects.filter(p=>{
    if(p.status==='deleted'||p.status==='archived') return false;
    if(user.id==='local') return true;
    return (p.assignedUserIds||[]).includes(user.id);
  });

  const active=projects.find(p=>p.id===activeId);
  const inProg=myProjects.filter(p=>p.currentStage<p.stages.length-1).length;
  const done=myProjects.filter(p=>p.currentStage>=p.stages.length-1).length;
  const allTasks=myProjects.flatMap(p=>p.stages.flatMap(s=>s.tasks.map(t=>({...t,projectName:p.name,projectId:p.id,stageName:s.name,projectColor:p.color||C.amber}))));
  const pendingTasks=allTasks.filter(t=>t.status!=='done');
  const overdueTasks=pendingTasks.filter(t=>t.dueDate&&new Date(t.dueDate)<new Date());
  const noteItems=[];
  myProjects.forEach(p=>{p.stages.forEach(s=>{if(s.notedAt&&(s.achievements||s.notes||s.nextSteps))noteItems.push({p,s,notedAt:s.notedAt,notedBy:s.notedBy||''});});});
  noteItems.sort((a,b)=>new Date(b.notedAt)-new Date(a.notedAt));

  useEffect(()=>{ dbTemplates().then(setTemplates).catch(()=>{}); },[]);
  const createAndOpen=async form=>{const id=await onCreate(form);setActiveId(id);setScreen('project');};

  if(screen==='create') return <CreateScreen templates={templates} profiles={profiles} onBack={()=>setScreen('home')} onCreate={createAndOpen}/>;
  if(screen==='project'&&active) return <ProjectScreen project={active} profiles={profiles} user={user} profile={profile} onSave={onSave} onArchive={onArchive} onSoftDelete={onSoftDelete} onDelete={async()=>{await onSoftDelete(active.id);setScreen('home');}} onBack={()=>setScreen('home')}/>;

  const TAB=({id,label,count})=>(
    <button onClick={()=>setActiveTab(id)} style={{flex:1,padding:'11px 4px',border:'none',background:'transparent',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:13,letterSpacing:1,color:activeTab===id?'#fff':C.t3,borderBottom:'3px solid '+(activeTab===id?C.amber:'transparent'),cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center',gap:5}}>
      {label}
      {count>0&&<span style={{background:activeTab===id?C.amber:'#1E3A5F',color:'#fff',borderRadius:10,padding:'1px 6px',fontSize:10}}>{count}</span>}
    </button>
  );

  return (
    <div style={{minHeight:'100vh',background:'#F1F5F9',color:C.t1,display:'flex',flexDirection:'column'}}>
      <div style={{background:'#0D1B3E',flexShrink:0}}>
        <div style={{padding:'12px 16px',display:'flex',alignItems:'center',gap:10,borderBottom:'1px solid #1E3A5F'}}>
          <img src={LOGO} style={{height:42,width:'auto',flexShrink:0}} alt="Paciffic Homes"/>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.amber,letterSpacing:1}}>SUPERVISOR PORTAL</div>
            <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:15,color:'#fff',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{profile?.full_name||user.email}</div>
          </div>
          <div style={{display:'flex',gap:6,flexShrink:0}}>
            {onSwitchView&&<button onClick={onSwitchView} style={{background:'transparent',border:'1px solid '+C.amber+'80',borderRadius:20,padding:'4px 12px',cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:11,color:C.amber}}>ADMIN</button>}
            <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:'#475569',background:'#1E3A5F',borderRadius:4,padding:'2px 6px',flexShrink:0}}>{APP_VERSION}</div>
            <button onClick={onSignOut} style={{background:'transparent',border:'1px solid #ffffff30',borderRadius:20,padding:'4px 10px',color:'#94A3B8',cursor:'pointer',fontSize:11,fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700}}>SIGN OUT</button>
          </div>
        </div>
        <div style={{display:'grid',gridTemplateColumns:'1fr 1fr 1fr',gap:1,background:'#1E3A5F'}}>
          {[['MY PROJECTS',myProjects.length,'#93C5FD'],['IN PROGRESS',inProg,C.amber],['COMPLETED',done,'#86EFAC']].map(([l,v,col])=>(
            <div key={l} style={{background:'#0D1B3E',padding:'14px 8px',textAlign:'center'}}>
              <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:44,color:col,lineHeight:1}}>{v}</div>
              <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:8,color:'#475569',marginTop:4,letterSpacing:0.5}}>{l}</div>
            </div>
          ))}
        </div>
        <div style={{display:'flex',background:'#0D1B3E',borderTop:'1px solid #1E3A5F'}}>
          <TAB id="projects" label="PROJECTS" count={myProjects.length}/>
          <TAB id="tasks" label="TASKS" count={pendingTasks.length}/>
          <TAB id="notes" label="NOTES" count={noteItems.length}/>
        </div>
      </div>

      <div style={{flex:1,overflowY:'auto',padding:'14px 14px 32px'}}>

        {activeTab==='projects'&&(
          <div>
            <SafeActivityFeed projects={myProjects} onSave={onSave}/>
            {overdueTasks.length>0&&(
              <div style={{background:'#FEF2F2',border:'1px solid #FECACA',borderRadius:12,padding:'12px 14px',marginBottom:12,display:'flex',alignItems:'center',gap:10}}>
                <span style={{fontSize:20}}>{"🚨"}</span>
                <div>
                  <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:15,color:'#DC2626'}}>{overdueTasks.length} OVERDUE {overdueTasks.length===1?"TASK":"TASKS"}</div>
                  <div style={{fontSize:11,color:'#991B1B'}}>Tap Tasks tab to review</div>
                </div>
              </div>
            )}
            <button onClick={()=>setScreen('create')} style={{...BS(C.amber),width:'100%',fontSize:15,letterSpacing:2,marginBottom:14,padding:'14px'}}>+ CREATE NEW PROJECT</button>
            {myProjects.length===0&&(
              <div style={{textAlign:'center',padding:'60px 20px',color:'#94A3B8'}}>
                <div style={{fontSize:48,marginBottom:12}}>{"🏗️"}</div>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontSize:22,fontWeight:700,color:'#64748B',marginBottom:8}}>NO PROJECTS ASSIGNED</div>
                <div style={{fontSize:13}}>Your admin will assign projects to you.</div>
              </div>
            )}
            {myProjects.map(p=>{
              const sc=p.stages.length,pct=sc<=1?0:Math.round((p.currentStage/(sc-1))*100),isDone=p.currentStage>=sc-1,pc=p.color||C.amber;
              const tt=p.stages.reduce((a,s)=>a+s.tasks.length,0),td=p.stages.reduce((a,s)=>a+s.tasks.filter(t=>t.status==='done').length,0);
              const ptasks=p.stages.flatMap(s=>s.tasks).filter(t=>t.status!=='done');
              return(
                <button key={p.id} onClick={()=>{setActiveId(p.id);setScreen('project');}}
                  style={{width:'100%',textAlign:'left',display:'block',background:'#fff',border:'1px solid #E2E8F0',borderLeft:'5px solid '+(isDone?C.green:pc),borderRadius:14,padding:'16px',marginBottom:12,cursor:'pointer',boxShadow:'0 1px 6px rgba(0,0,0,0.06)'}}>
                  <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',marginBottom:10}}>
                    <div style={{flex:1,minWidth:0,paddingRight:12}}>
                      <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:22,color:'#0F172A',marginBottom:3,lineHeight:1.1}}>{p.name}</div>
                      <div style={{color:'#64748B',fontSize:12,marginBottom:2}}>{"📍 "}{p.location||"—"}</div>
                      <div style={{color:'#64748B',fontSize:12}}>{"👤 "}{p.client||"—"}</div>
                    </div>
                    <div style={{background:isDone?C.green:pc,borderRadius:12,padding:'10px 14px',textAlign:'center',flexShrink:0}}>
                      <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:30,color:'#fff',lineHeight:1}}>{pct}<span style={{fontSize:14}}>%</span></div>
                    </div>
                  </div>
                  <div style={{background:'#F8FAFC',borderRadius:8,padding:'8px 12px',marginBottom:10}}>
                    <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:pc,letterSpacing:0.5,marginBottom:2}}>STAGE {p.currentStage+1}/{sc}</div>
                    <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:15,color:'#0F172A'}}>{p.stages[p.currentStage]?.name}</div>
                  </div>
                  <div style={{display:'flex',alignItems:'center',gap:10}}>
                    <div style={{flex:1,background:'#E2E8F0',borderRadius:4,height:8}}>
                      <div style={{width:pct+'%',height:'100%',background:isDone?C.green:pc,borderRadius:4}}/>
                    </div>
                    <span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:'#94A3B8',flexShrink:0}}>{td}/{tt} tasks</span>
                  </div>
                  {ptasks.length>0&&(
                    <div style={{marginTop:10,paddingTop:10,borderTop:'1px solid #F1F5F9'}}>
                      <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:'#94A3B8',marginBottom:6}}>PENDING TASKS</div>
                      {ptasks.slice(0,2).map((t,i)=>(
                        <div key={i} style={{display:'flex',alignItems:'center',gap:8,marginBottom:4}}>
                          <div style={{width:6,height:6,borderRadius:'50%',background:pc,flexShrink:0}}/>
                          <div style={{fontSize:12,color:'#334155',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{t.title}</div>
                        </div>
                      ))}
                      {ptasks.length>2&&<div style={{fontSize:11,color:'#94A3B8',paddingLeft:14}}>+{ptasks.length-2} more</div>}
                    </div>
                  )}
                </button>
              );
            })}
          </div>
        )}

        {activeTab==='tasks'&&(
          <div>
            {pendingTasks.length===0?(
              <div style={{textAlign:'center',padding:'60px 20px',color:'#94A3B8'}}>
                <div style={{fontSize:48,marginBottom:12}}>{"✅"}</div>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontSize:22,fontWeight:700,color:'#64748B'}}>ALL CLEAR</div>
                <div style={{fontSize:13,marginTop:6}}>No pending tasks across your projects.</div>
              </div>
            ):(
              <div>
                {overdueTasks.length>0&&(
                  <div style={{background:'#FEF2F2',border:'1px solid #FECACA',borderRadius:10,padding:'10px 14px',marginBottom:12,display:'flex',alignItems:'center',gap:10}}>
                    <span style={{fontSize:20}}>{"🚨"}</span>
                    <div>
                      <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:15,color:'#DC2626'}}>{overdueTasks.length} OVERDUE</div>
                      <div style={{fontSize:11,color:'#991B1B'}}>Needs immediate attention</div>
                    </div>
                  </div>
                )}
                {[...pendingTasks].sort((a,b)=>{
                  const ao=a.dueDate&&new Date(a.dueDate)<new Date(),bo=b.dueDate&&new Date(b.dueDate)<new Date();
                  return (ao&&!bo)?-1:(!ao&&bo)?1:0;
                }).map((t,i)=>{
                  const isOv=t.dueDate&&new Date(t.dueDate)<new Date();
                  return(
                    <button key={i} onClick={()=>{const p=myProjects.find(p=>p.id===t.projectId);if(p){setActiveId(p.id);setScreen('project');}}}
                      style={{width:'100%',textAlign:'left',background:isOv?'#FEF2F2':'#fff',border:'1px solid '+(isOv?'#FECACA':'#E2E8F0'),borderLeft:'4px solid '+(isOv?'#DC2626':t.projectColor),borderRadius:12,padding:'13px 14px',marginBottom:8,cursor:'pointer'}}>
                      <div style={{display:'flex',justifyContent:'space-between',gap:8}}>
                        <div style={{flex:1,minWidth:0}}>
                          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:17,color:isOv?'#DC2626':'#0F172A',marginBottom:3}}>{t.title}</div>
                          <div style={{fontSize:11,color:'#64748B'}}>{t.projectName} {"·"} {t.stageName}</div>
                          {t.dueDate&&<div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:isOv?'#DC2626':'#94A3B8',marginTop:3}}>DUE {new Date(t.dueDate).toLocaleDateString('en-AU',{day:'numeric',month:'short'})}</div>}
                        </div>
                        {t.priority&&<div style={{background:isOv?'#DC2626':t.projectColor,borderRadius:6,padding:'3px 8px',alignSelf:'flex-start',flexShrink:0}}>
                          <span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:'#fff'}}>{t.priority}</span>
                        </div>}
                      </div>
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {activeTab==='notes'&&(
          <div>
            {noteItems.length===0&&(
              <div style={{textAlign:'center',padding:'60px 20px',color:'#94A3B8'}}>
                <div style={{fontSize:48,marginBottom:12}}>{"📋"}</div>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontSize:22,fontWeight:700,color:'#64748B'}}>NO NOTES YET</div>
                <div style={{fontSize:13,marginTop:6}}>Stage notes from your projects appear here.</div>
              </div>
            )}
            {noteItems.map(({p,s,notedAt,notedBy},i)=>{
              const d=Date.now()-new Date(notedAt).getTime();
              const mins=Math.floor(d/60000),hrs=Math.floor(mins/60),days=Math.floor(hrs/24);
              const ago=days>0?days+"d ago":hrs>0?hrs+"h ago":mins>0?mins+"m ago":"just now";
              return(
                <button key={i} onClick={()=>{setActiveId(p.id);setScreen('project');}}
                  style={{width:'100%',textAlign:'left',background:'#fff',border:'1px solid #E2E8F0',borderLeft:'4px solid #7C3AED',borderRadius:12,padding:'14px',marginBottom:10,cursor:'pointer'}}>
                  <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',marginBottom:6}}>
                    <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:16,color:'#0F172A'}}>{p.name}</div>
                    <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:'#7C3AED',flexShrink:0,marginLeft:8,background:'#F5F3FF',borderRadius:4,padding:'2px 6px'}}>{ago}</div>
                  </div>
                  <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:'#7C3AED',marginBottom:8}}>{s.name.toUpperCase()}{notedBy?" · "+notedBy.split("@")[0].toUpperCase():""}</div>
                  {s.achievements&&<div style={{display:'flex',gap:8,marginBottom:5,alignItems:'flex-start'}}><span style={{fontSize:14,flexShrink:0}}>{"✅"}</span><div style={{fontSize:13,color:'#166534'}}>{s.achievements}</div></div>}
                  {s.notes&&<div style={{display:'flex',gap:8,marginBottom:5,alignItems:'flex-start'}}><span style={{fontSize:14,flexShrink:0}}>{"📝"}</span><div style={{fontSize:13,color:'#334155'}}>{s.notes}</div></div>}
                  {s.nextSteps&&<div style={{display:'flex',gap:8,alignItems:'flex-start'}}><span style={{fontSize:14,flexShrink:0}}>{"→"}</span><div style={{fontSize:13,color:'#1D4ED8'}}>{s.nextSteps}</div></div>}
                </button>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
// ── CREATE SCREEN ────────────────────────────────────────────────────────────
function CreateScreen({onBack,onCreate,templates=[],profiles=[]}) {
  const [step,setStep]=useState(templates.length>0?'template':'details');
  const [selTemplate,setSelTemplate]=useState(null);
  const [selSupervisorIds,setSelSupervisorIds]=useState([]);
  const [form,setForm]=useState({name:'',location:'',client:'',startDate:new Date().toISOString().slice(0,10),color:randProjColor()});
  const set=k=>e=>setForm(f=>({...f,[k]:e.target.value}));

  // Only show supervisor-role profiles
  const supervisors=profiles.filter(p=>p.role==='supervisor'||p.role==='admin');

  const toggleSup=(id)=>{
    setSelSupervisorIds(prev=>prev.includes(id)?prev.filter(x=>x!==id):[...prev,id]);
  };

  const handleCreate=()=>{
    if(!form.name.trim()) return;
    let stages;
    if(selTemplate){
      stages=selTemplate.stages.map((s,i)=>({
        id:uid(), name:s.name,
        status:i===0?'active':'pending',
        tasks:(s.tasks||[]).map(t=>({...t,id:uid(),status:'todo',createdAt:new Date().toISOString()})),
        photos:[], notes:'', achievements:'', nextSteps:'',
      }));
    } else {
      stages=buildDefaultStages();
    }
    // Build supervisor entries from selected profiles
    const supervisorEntries=selSupervisorIds.map(id=>{
      const prof=profiles.find(p=>p.id===id);
      return prof?{id:uid(),userId:prof.id,name:prof.full_name||prof.email,role:'Site Supervisor',email:prof.email,phone:'',notes:''}:null;
    }).filter(Boolean);

    onCreate({...form,stages,supervisors:supervisorEntries,assignedUserIds:selSupervisorIds});
  };

  return (
    <div style={{minHeight:'100vh',background:C.bg,color:C.t1}}>
      <div style={{background:C.surface,borderBottom:'3px solid '+C.amber,padding:'14px 16px',display:'flex',alignItems:'center',gap:12}}>
        <button onClick={step==='details'&&templates.length>0?()=>setStep('template'):onBack} style={{background:'transparent',border:'none',color:C.amber,cursor:'pointer',fontSize:26,lineHeight:1,padding:'0 8px'}}>‹</button>
        <div>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:20,letterSpacing:2}}>
            {step==='template'?'CHOOSE A TEMPLATE':'PROJECT DETAILS'}
          </div>
          <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.amber,letterSpacing:1}}>
            {step==='template'?'STEP 1 OF 2':'STEP 2 OF 2'}
          </div>
        </div>
      </div>

      {step==='template'&&(
        <div style={{width:'100%',maxWidth:900,margin:'0 auto',padding:'22px 24px'}}>
          <Lbl style={{marginBottom:16}}>SELECT A TEMPLATE — or start blank</Lbl>

          {/* Blank option */}
          <button onClick={()=>{setSelTemplate(null);setStep('details');}}
            style={{width:'100%',textAlign:'left',background:selTemplate===null?C.amber+'15':C.card,border:'2px solid '+(selTemplate===null?C.amber:C.border),borderRadius:12,padding:'14px 18px',marginBottom:12,cursor:'pointer',display:'flex',alignItems:'center',gap:14}}>
            <div style={{width:42,height:42,borderRadius:10,background:C.border,display:'flex',alignItems:'center',justifyContent:'center',fontSize:20,flexShrink:0}}>📋</div>
            <div>
              <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:17,color:C.t1,marginBottom:2}}>BLANK PROJECT</div>
              <div style={{fontSize:12,color:C.t2}}>Start with default stages, no pre-filled tasks</div>
            </div>
          </button>

          {templates.map(t=>(
            <button key={t.id} onClick={()=>{setSelTemplate(t);setStep('details');}}
              style={{width:'100%',textAlign:'left',background:selTemplate?.id===t.id?C.amber+'15':C.card,border:'2px solid '+(selTemplate?.id===t.id?C.amber:C.border),borderLeft:'4px solid '+C.amber,borderRadius:12,padding:'14px 18px',marginBottom:10,cursor:'pointer',display:'flex',alignItems:'flex-start',gap:14}}>
              <div style={{width:42,height:42,borderRadius:10,background:C.amber+'20',display:'flex',alignItems:'center',justifyContent:'center',fontSize:20,flexShrink:0}}>📐</div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:17,color:C.t1,marginBottom:2}}>{t.name}</div>
                {t.description&&<div style={{fontSize:12,color:C.t2,marginBottom:6}}>{t.description}</div>}
                <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.amber,marginBottom:8}}>
                  {t.stages?.length||0} STAGES · {t.stages?.reduce((a,s)=>a+(s.tasks?.length||0),0)||0} TASKS PRE-LOADED
                </div>
                <div style={{display:'flex',flexWrap:'wrap',gap:5}}>
                  {(t.stages||[]).slice(0,4).map(s=>(
                    <div key={s.id} style={{background:C.bg,border:'1px solid '+C.border,borderRadius:4,padding:'2px 7px',fontSize:10,color:C.t2}}>
                      {s.name} {s.tasks?.length>0&&<span style={{color:C.amber}}>({s.tasks.length})</span>}
                    </div>
                  ))}
                  {(t.stages||[]).length>4&&<div style={{background:C.bg,border:'1px solid '+C.border,borderRadius:4,padding:'2px 7px',fontSize:10,color:C.t3}}>+{t.stages.length-4} more</div>}
                </div>
              </div>
            </button>
          ))}
        </div>
      )}

      {step==='details'&&(
        <div style={{width:'100%',maxWidth:900,margin:'0 auto',padding:'24px 24px'}}>
          {selTemplate&&(
            <div style={{background:C.amber+'15',border:'1px solid '+C.amber+'60',borderRadius:10,padding:'10px 14px',marginBottom:20,display:'flex',alignItems:'center',gap:10}}>
              <span style={{fontSize:18}}>📐</span>
              <div>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:13,color:C.amber}}>USING TEMPLATE: {selTemplate.name.toUpperCase()}</div>
                <div style={{fontSize:12,color:C.t2}}>{selTemplate.stages?.length} stages · {selTemplate.stages?.reduce((a,s)=>a+(s.tasks?.length||0),0)} tasks will be pre-loaded</div>
              </div>
            </div>
          )}
          {[['PROJECT NAME','name','e.g. Riverside Apartments — Block C'],['SITE LOCATION','location','e.g. 42 Main St, Melbourne'],['CLIENT / OWNER','client','e.g. Riverside Properties Ltd']].map(([label,key,ph])=>(
            <div key={key} style={{marginBottom:16}}>
              <label style={LS}>{label}</label>
              <input value={form[key]} onChange={set(key)} placeholder={ph} style={IS()}/>
            </div>
          ))}
          <div style={{marginBottom:24}}><label style={LS}>START DATE</label><input type="date" value={form.startDate} onChange={set('startDate')} style={IS()}/></div>

          {/* Project colour */}
          <div style={{marginBottom:24}}>
            <label style={LS}>PROJECT COLOUR</label>
            <div style={{display:'flex',flexWrap:'wrap',gap:8,marginBottom:8}}>
              {PROJECT_COLORS.map(pc=>(
                <button key={pc.val} onClick={()=>setForm(f=>({...f,color:pc.val}))} title={pc.name}
                  style={{width:32,height:32,borderRadius:'50%',background:pc.val,border:form.color===pc.val?'3px solid #0D1B3E':'3px solid transparent',cursor:'pointer',boxShadow:form.color===pc.val?'0 0 0 2px '+pc.val+'60':'none',transition:'all 0.15s'}}/>
              ))}
            </div>
            <div style={{display:'flex',alignItems:'center',gap:8}}>
              <div style={{width:20,height:20,borderRadius:'50%',background:form.color||C.amber,flexShrink:0}}/>
              <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:600,fontSize:13,color:C.t2}}>{PROJECT_COLORS.find(pc=>pc.val===form.color)?.name||'Custom'}</span>
              <button onClick={()=>setForm(f=>({...f,color:randProjColor()}))} style={{marginLeft:'auto',...BS('transparent',C.t2),border:'1px solid '+C.border,padding:'4px 10px',fontSize:11}}>🎲 RANDOM</button>
            </div>
          </div>

          {/* Supervisor allocation */}
          {supervisors.length>0&&(
            <div style={{marginBottom:24}}>
              <label style={LS}>ASSIGN SUPERVISOR(S)</label>
              <div style={{display:'flex',flexDirection:'column',gap:8}}>
                {supervisors.map(sup=>{
                  const selected=selSupervisorIds.includes(sup.id);
                  const ini=(sup.full_name||sup.email||'?').split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();
                  return(
                    <button key={sup.id} onClick={()=>toggleSup(sup.id)}
                      style={{display:'flex',alignItems:'center',gap:12,padding:'10px 14px',background:selected?C.amber+'15':C.bg,border:'1px solid '+(selected?C.amber:C.border),borderRadius:10,cursor:'pointer',textAlign:'left',width:'100%',transition:'all 0.15s'}}>
                      <div style={{width:36,height:36,borderRadius:'50%',background:selected?C.amber:C.border,display:'flex',alignItems:'center',justifyContent:'center',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:13,color:selected?'#000':C.t3,flexShrink:0,transition:'all 0.15s'}}>
                        {ini}
                      </div>
                      <div style={{flex:1}}>
                        <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:16,color:C.t1}}>{sup.full_name||'—'}</div>
                        <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3}}>{sup.email}</div>
                      </div>
                      <div style={{width:22,height:22,borderRadius:'50%',background:selected?C.green:'transparent',border:'2px solid '+(selected?C.green:C.border),display:'flex',alignItems:'center',justifyContent:'center',flexShrink:0,fontSize:13,color:'#fff',transition:'all 0.15s'}}>
                        {selected?"✓":''}
                      </div>
                    </button>
                  );
                })}
              </div>
              {selSupervisorIds.length>0&&(
                <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.green,marginTop:8}}>
                  ✓ {selSupervisorIds.length} supervisor{selSupervisorIds.length!==1?'s':''} will be assigned to this project
                </div>
              )}
            </div>
          )}
          {supervisors.length===0&&(
            <div style={{background:C.bg,border:'1px solid '+C.border,borderRadius:10,padding:'12px 14px',marginBottom:24,fontFamily:"'Barlow',sans-serif",fontSize:13,color:C.t3}}>
              👷 No supervisors registered yet — you can assign supervisors after creating the project via the Team tab
            </div>
          )}
          <button onClick={handleCreate} style={{...BS(C.amber),width:'100%',padding:'14px',fontSize:16,letterSpacing:2}}>CREATE PROJECT</button>
          <button onClick={()=>templates.length>0?setStep('template'):onBack()} style={{...BS('transparent',C.t2),width:'100%',padding:'12px',fontSize:14,marginTop:10,border:'1px solid '+C.border}}>
            {templates.length>0?"← CHANGE TEMPLATE":'CANCEL'}
          </button>
        </div>
      )}
    </div>
  );
}

// ── PROJECT SCREEN ───────────────────────────────────────────────────────────
function ProjectScreen({project:init,onSave,onDelete,onArchive,onSoftDelete,onBack,user,profile}) {
  const [p,setP]=useState(init);
  const [tab,setTab]=useState('overview');
  const [editingName,setEditingName]=useState(false);
  const [nameVal,setNameVal]=useState(init.name);
  const isAdmin=profile?.role==='admin'||profile?.role==='superadmin'||profile?.role==='super_admin';
  const [jumpManage,setJumpManage]=useState(false);
  const [showPasswordModal,setShowPasswordModal]=useState(null);
  const [showUndo,setShowUndo]=useState(false);
  const update=useCallback(next=>{setP(next);onSave(next);},[onSave]);
  const stage=p.stages[p.currentStage];
  const sc=p.stages.length;
  const pct=sc<=1?0:Math.round((p.currentStage/(sc-1))*100);
  const td=p.stages.reduce((a,s)=>a+s.tasks.filter(t=>t.status==='done').length,0);
  const tt=p.stages.reduce((a,s)=>a+s.tasks.length,0);
  const advance=()=>{if(p.currentStage>=sc-1)return;const stages=p.stages.map((s,i)=>i===p.currentStage?{...s,status:'complete'}:i===p.currentStage+1?{...s,status:'active'}:s);update({...p,stages,currentStage:p.currentStage+1});};

  // Undo stage — option to also reset tasks or leave them
  const doUndoStage=(resetTasks)=>{
    const prevIdx=p.currentStage-1;
    const stages=p.stages.map((s,i)=>{
      if(i===p.currentStage) return {...s,status:'pending'};
      if(i===prevIdx){
        if(resetTasks){
          // Reopen all done tasks in the previous stage back to in-progress
          const tasks=s.tasks.map(t=>t.status==='done'?{...t,status:'doing'}:t);
          return {...s,status:'active',tasks};
        }
        return {...s,status:'active'};
      }
      return s;
    });
    update({...p,stages,currentStage:prevIdx});
    setShowUndo(false);
  };
  const TABS=[{id:'overview',icon:"📋",label:'OVERVIEW'},{id:'tasks',icon:"✅",label:'TASKS'},{id:'photos',icon:"📸",label:'PHOTOS'},{id:'notes',icon:"📝",label:'NOTES'},{id:'files',icon:"📁",label:'FILES'},{id:'team',icon:"👷",label:'TEAM'}];
  return (
    <div style={{minHeight:'100vh',background:C.bg,color:C.t1,display:'flex',flexDirection:'column'}}>
      <div style={{background:C.surface,borderBottom:'3px solid '+C.amber,flexShrink:0}}>
        <div style={{padding:'12px 16px',display:'flex',alignItems:'center',gap:10}}>
          <button onClick={onBack} style={{background:'transparent',border:'none',color:C.amber,cursor:'pointer',fontSize:26,lineHeight:1,padding:'0 8px',flexShrink:0}}>‹</button>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:18,color:C.t1,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>
              {isAdmin&&editingName?(
                <div style={{display:'flex',alignItems:'center',gap:6}}>
                  <input autoFocus value={nameVal} onChange={e=>setNameVal(e.target.value)}
                    onKeyDown={e=>{if(e.key==='Enter'){const updated={...p,name:nameVal.trim()||p.name};setP(updated);onSave(updated);setEditingName(false);}if(e.key==='Escape'){setNameVal(p.name);setEditingName(false);}}}
                    style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:16,border:'2px solid '+C.amber,borderRadius:6,background:'#fffbeb',color:C.t1,outline:'none',flex:1,padding:'4px 8px',minWidth:0}}/>
                  <button onClick={()=>{const updated={...p,name:nameVal.trim()||p.name};setP(updated);onSave(updated);setEditingName(false);}} style={{background:C.green,border:'none',borderRadius:6,padding:'4px 10px',color:'#fff',cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:12,flexShrink:0}}>SAVE</button>
                  <button onClick={()=>{setNameVal(p.name);setEditingName(false);}} style={{background:C.border,border:'none',borderRadius:6,padding:'4px 8px',color:C.t2,cursor:'pointer',fontSize:12,flexShrink:0}}>✕</button>
                </div>
              ):(
                <span style={{display:'flex',alignItems:'center',gap:6}}>
                  {p.name}
                  {isAdmin&&<button onClick={()=>{setNameVal(p.name);setEditingName(true);}} style={{background:'transparent',border:'none',cursor:'pointer',fontSize:14,padding:0,lineHeight:1,flexShrink:0}}>✏️</button>}
                </span>
              )}
            </div>
            <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t2}}>📍 {p.location} · 👤 {p.client}</div>
          </div>
          <div style={{textAlign:'right',flexShrink:0}}>
            <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:22,color:C.amber,lineHeight:1}}>{pct}%</div>
            <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.t3}}>COMPLETE</div>
          </div>
        </div>
        <div style={{background:C.amber+'12',borderTop:'1px solid '+C.amber+'30',padding:'10px 16px',display:'flex',justifyContent:'space-between',alignItems:'center'}}>
          <div>
            <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.amber,letterSpacing:1}}>STAGE {p.currentStage+1}/{sc}{tt>0?' · '+td+'/'+tt+' TASKS':''}</div>
            <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:18}}>{stage?.name}</div>
          </div>
          <div style={{display:'flex',gap:8,flexWrap:'wrap',justifyContent:'flex-end'}}>
            <button onClick={()=>{setJumpManage(true);setTab('overview');}} style={{...BS('transparent',C.t2),padding:'6px 10px',border:'1px solid '+C.border,fontSize:12}}>⚙ STAGES</button>
            <button onClick={()=>setShowPasswordModal({action:'archive',label:'Archive "'+p.name+'"',onConfirm:()=>{onArchive&&onArchive(p.id);onBack();}})} style={{...BS('transparent',C.t2),padding:'6px 10px',border:'1px solid '+C.border,fontSize:12}}>📦</button>
            <button onClick={()=>setShowPasswordModal({action:'delete',label:'Move "'+p.name+'" to Trash',onConfirm:()=>{onSoftDelete?onSoftDelete(p.id):onDelete();onBack();}})} style={{...BS('transparent',C.red),padding:'6px 10px',border:'1px solid '+C.red+'60',fontSize:12}}>🗑</button>
            {p.currentStage>0&&<button onClick={()=>setShowUndo(true)} title="Undo last stage completion" style={{...BS('transparent',C.purple),padding:'6px 10px',border:'1px solid '+C.purple+'60',fontSize:12}}>↩ UNDO</button>}
            {p.currentStage<sc-1&&<button onClick={advance} style={{...BS(C.green),padding:'6px 12px',fontSize:12}}>✓ COMPLETE</button>}
          </div>
        </div>
      </div>
      <div style={{background:C.surface,borderBottom:'1px solid '+C.border,display:'flex',flexShrink:0}}>
        {TABS.map(t=>(
          <button key={t.id} onClick={()=>setTab(t.id)} style={{flex:1,padding:'10px 2px 7px',background:'transparent',border:'none',borderBottom:tab===t.id?'3px solid '+(p.color||C.amber):'3px solid transparent',color:tab===t.id?C.amber:C.t3,cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:10,letterSpacing:0.5,display:'flex',flexDirection:'column',alignItems:'center',gap:2}}>
            <span style={{fontSize:17}}>{t.icon}</span><span>{t.label}</span>
          </button>
        ))}
      </div>
      <div style={{flex:1,overflow:'auto'}}>
        {tab==='overview'&&<OverviewTab p={p} update={update} jumpManage={jumpManage} onJumped={()=>setJumpManage(false)}/>}
        {tab==='tasks'   &&<TasksTab p={p} stage={stage} update={update}/>}
        {tab==='photos'  &&<PhotosTab projectId={p.id} stage={stage} profile={profile}/>}
        {tab==='notes'   &&<NotesTab p={p} stage={stage} update={update} user={user}/>}
        {tab==='team'    &&<TeamTab p={p} update={update}/>}
        {tab==='files'   &&<FilesTab p={p} update={update}/>}
      </div>
      {showUndo&&(()=>{
        const prevStage=p.stages[p.currentStage-1];
        const doneTasks=prevStage?.tasks?.filter(t=>t.status==='done')||[];
        return(
          <div style={{position:'fixed',inset:0,background:'#000c',display:'flex',alignItems:'center',justifyContent:'center',zIndex:999,padding:20}}>
            <div style={{background:C.surface,border:'1px solid '+C.purple,borderRadius:16,padding:28,maxWidth:420,width:'100%'}}>
              <div style={{fontSize:32,marginBottom:10,textAlign:'center'}}>↩</div>
              <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:22,marginBottom:6,textAlign:'center'}}>UNDO STAGE COMPLETION</div>
              <div style={{color:C.t2,fontSize:13,marginBottom:16,textAlign:'center'}}>
                Reverting <strong style={{color:C.amber}}>{prevStage?.name}</strong> back to active.
              </div>
              {doneTasks.length>0?(
                <div style={{background:C.card,border:'1px solid '+C.border,borderRadius:10,padding:'14px',marginBottom:14}}>
                  <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:11,letterSpacing:2,color:C.t3,marginBottom:10}}>
                    {doneTasks.length} COMPLETED TASK{doneTasks.length!==1?'S':''} IN THIS STAGE — WHAT SHOULD HAPPEN?
                  </div>
                  {doneTasks.slice(0,4).map(t=>(
                    <div key={t.id} style={{display:'flex',alignItems:'center',gap:8,marginBottom:5}}>
                      <div style={{width:6,height:6,borderRadius:'50%',background:C.green,flexShrink:0}}/>
                      <div style={{fontSize:13,color:C.t1,lineHeight:1.3}}>{t.title}</div>
                    </div>
                  ))}
                  {doneTasks.length>4&&<div style={{fontSize:12,color:C.t3,marginTop:6}}>+{doneTasks.length-4} more tasks</div>}
                  <div style={{display:'flex',gap:10,marginTop:14}}>
                    <button onClick={()=>doUndoStage(false)} style={{flex:1,background:C.bg,border:'1px solid '+C.green,borderRadius:8,padding:'12px 8px',cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:12,color:C.green,textAlign:'center',lineHeight:1.4}}>
                      ✓ KEEP TASKS<br/>AS DONE
                    </button>
                    <button onClick={()=>doUndoStage(true)} style={{flex:1,background:C.bg,border:'1px solid '+C.amber,borderRadius:8,padding:'12px 8px',cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:12,color:C.amber,textAlign:'center',lineHeight:1.4}}>
                      ↩ REOPEN TASKS<br/>TO IN PROGRESS
                    </button>
                  </div>
                </div>
              ):(
                <button onClick={()=>doUndoStage(false)} style={{...BS(C.purple,'#fff'),width:'100%',padding:'12px',fontSize:15,letterSpacing:1,marginBottom:12}}>UNDO STAGE</button>
              )}
              <button onClick={()=>setShowUndo(false)} style={{...BS('transparent',C.t3),width:'100%',padding:'10px',border:'1px solid '+C.border,fontSize:13}}>CANCEL — KEEP AS COMPLETE</button>
            </div>
          </div>
        );
      })()}
      {showPasswordModal&&<AdminPasswordModal action={showPasswordModal.action} actionLabel={showPasswordModal.label} user={user||{id:'local',email:'admin@local'}} onConfirm={()=>{showPasswordModal.onConfirm();setShowPasswordModal(null);}} onCancel={()=>setShowPasswordModal(null)}/>}
    </div>
  );
}

// ── OVERVIEW TAB ─────────────────────────────────────────────────────────────
function OverviewTab({p,update,jumpManage,onJumped}) {
  const [managing,setManaging]=useState(false);
  const [names,setNames]=useState(p.stages.map(s=>s.name));
  const [newName,setNewName]=useState('');
  useEffect(()=>{if(jumpManage){setManaging(true);onJumped();}},[jumpManage]);
  useEffect(()=>{setNames(p.stages.map(s=>s.name));},[p.stages.length]);
  const [expandedStages,setExpandedStages]=useState({[p.currentStage]:true});
  const toggleStage=i=>setExpandedStages(prev=>({...prev,[i]:!prev[i]}));
  const moveTask=(sid,tid,st)=>{const stages=p.stages.map(s=>s.id===sid?{...s,tasks:s.tasks.map(t=>t.id===tid?{...t,status:st}:t)}:s);update({...p,stages});};
  const canDel=s=>s.status==='pending'&&!s.tasks.length&&p.stages.length>1;
  const saveNames=()=>{const stages=p.stages.map((s,i)=>({...s,name:names[i]?.trim()||s.name}));update({...p,stages});setManaging(false);};
  const addStage=()=>{if(!newName.trim())return;const s={id:uid(),name:newName.trim(),status:'pending',tasks:[],photos:[],notes:'',achievements:'',nextSteps:''};const stages=[...p.stages,s];update({...p,stages});setNames(stages.map(x=>x.name));setNewName('');};
  const delStage=i=>{if(!canDel(p.stages[i]))return;const stages=p.stages.filter((_,idx)=>idx!==i);update({...p,stages,currentStage:Math.min(p.currentStage,stages.length-1)});setNames(stages.map(s=>s.name));};
  const move=(i,dir)=>{const j=i+dir;if(j<0||j>=p.stages.length)return;const stages=[...p.stages];[stages[i],stages[j]]=[stages[j],stages[i]];const ns=[...names];[ns[i],ns[j]]=[ns[j],ns[i]];let cs=p.currentStage;if(i===cs)cs=j;else if(j===cs)cs=i;update({...p,stages,currentStage:cs});setNames(ns);};
  if(managing) return (
    <div style={{padding:16}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>
          <Lbl style={{marginBottom:0}}>MANAGE STAGES</Lbl>
          <div style={{display:'flex',alignItems:'center',gap:6}}>
            <span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3}}>PROJECT COLOUR:</span>
            {PROJECT_COLORS.map(pc=>(
              <button key={pc.val} onClick={()=>update({...p,color:pc.val})} title={pc.name}
                style={{width:22,height:22,borderRadius:'50%',background:pc.val,border:(p.color||C.amber)===pc.val?'3px solid #0D1B3E':'2px solid transparent',cursor:'pointer',transition:'all 0.1s'}}/>
            ))}
            <button onClick={()=>update({...p,color:randProjColor()})} style={{border:'1px solid '+C.border,borderRadius:5,background:'transparent',padding:'3px 8px',fontSize:11,cursor:'pointer',color:C.t2}}>🎲</button>
          </div>
        </div>
        <div style={{display:'flex',gap:8}}>
          <button onClick={()=>{setNames(p.stages.map(s=>s.name));setManaging(false);}} style={{...BS('transparent',C.t2),border:'1px solid '+C.border,padding:'6px 14px'}}>CANCEL</button>
          <button onClick={saveNames} style={{...BS(C.amber),padding:'6px 16px'}}>SAVE</button>
        </div>
      </div>
      {p.stages.map((s,i)=>{const sc=s.status==='complete'?C.green:s.status==='active'?C.amber:C.t3;const d=canDel(s);return(
        <div key={s.id} style={{background:C.card,border:'1px solid '+C.border,borderRadius:8,padding:'9px 12px',marginBottom:8,display:'flex',gap:8,alignItems:'center'}}>
          <div style={{width:7,height:7,borderRadius:'50%',background:sc,flexShrink:0}}/>
          <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3,width:18,flexShrink:0}}>{i+1}</div>
          <input value={names[i]??s.name} onChange={e=>setNames(ns=>ns.map((n,idx)=>idx===i?e.target.value:n))} style={IS({flex:1,padding:'7px 10px'})}/>
          {s.status!=='pending'&&<span style={{fontFamily:"'Barlow Condensed',sans-serif",fontSize:10,fontWeight:700,color:sc,flexShrink:0,letterSpacing:1}}>{s.status==='active'?'ACTIVE':'DONE'}</span>}
          <button onClick={()=>move(i,-1)} disabled={i===0} style={{background:'transparent',border:'1px solid '+C.border,borderRadius:5,cursor:i===0?'default':'pointer',width:26,height:26,color:i===0?C.border:C.t2,display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,flexShrink:0}}>▲</button>
          <button onClick={()=>move(i,1)} disabled={i>=p.stages.length-1} style={{background:'transparent',border:'1px solid '+C.border,borderRadius:5,cursor:i>=p.stages.length-1?'default':'pointer',width:26,height:26,color:i>=p.stages.length-1?C.border:C.t2,display:'flex',alignItems:'center',justifyContent:'center',fontSize:11,flexShrink:0}}>▼</button>
          <button onClick={()=>delStage(i)} disabled={!d} style={{background:'transparent',border:'none',color:d?C.red:C.border,cursor:d?'pointer':'default',fontSize:20,lineHeight:1,padding:'0 2px',flexShrink:0}}>×</button>
        </div>
      );})}
      <div style={{marginTop:16,background:C.surface,border:'1px dashed '+C.amber+'50',borderRadius:8,padding:16}}>
        <Lbl style={{marginBottom:10}}>ADD NEW STAGE</Lbl>
        <div style={{display:'flex',gap:8}}>
          <input value={newName} onChange={e=>setNewName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&addStage()} placeholder="e.g. Steel Fixing, Tiling..." style={IS({flex:1})}/>
          <button onClick={addStage} style={{...BS(C.amber),padding:'10px 16px'}}>ADD</button>
        </div>
      </div>
    </div>
  );
  

  return (
    <div style={{padding:14}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:14}}>
        <Lbl style={{marginBottom:0}}>STAGE PIPELINE — tap any stage to expand</Lbl>
        <button onClick={()=>setManaging(true)} style={{...BS('transparent',C.t2),border:'1px solid '+C.border,padding:'5px 12px',fontSize:12}}>⚙ MANAGE STAGES</button>
      </div>
      {p.stages.map((s,i)=>{
        const isA=i===p.currentStage,isD=s.status==='complete',isP=s.status==='pending';
        const stageCol=getStagColor(i); const col=isD?C.green:isA?stageCol:C.t3;
        const doneCnt=s.tasks.filter(t=>t.status==='done').length;
        const doingTasks=s.tasks.filter(t=>t.status==='doing');
        const todoTasks=s.tasks.filter(t=>t.status==='todo');
        const doneTasks=s.tasks.filter(t=>t.status==='done');
        const isExpanded=!!expandedStages[i];
        return(
          <div key={s.id} style={{display:'flex',alignItems:'stretch'}}>
            <div style={{display:'flex',flexDirection:'column',alignItems:'center',width:34,flexShrink:0}}>
              <div style={{width:28,height:28,borderRadius:'50%',background:isD?C.green:isA?C.amber:C.border,display:'flex',alignItems:'center',justifyContent:'center',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:12,color:isD||isA?'#000':C.t3,marginTop:8,flexShrink:0,cursor:'pointer'}} onClick={()=>toggleStage(i)}>{isD?"✓":i+1}</div>
              {i<p.stages.length-1&&<div style={{flex:1,width:2,background:isD?C.green:C.border,minHeight:16,marginTop:2}}/>}
            </div>
            <div style={{flex:1,marginLeft:10,marginBottom:8}}>
              <div style={{background:isA?C.card:C.surface,border:'1px solid '+(isA?C.amber:C.border),borderRadius:10,overflow:'hidden',boxShadow:isA?'0 2px 8px rgba(0,0,0,0.08)':'none',opacity:isP&&!isExpanded?0.6:1}}>
                {/* Clickable header */}
                <button onClick={()=>toggleStage(i)} style={{width:'100%',background:'transparent',border:'none',cursor:'pointer',padding:'10px 14px',display:'flex',justifyContent:'space-between',alignItems:'center',textAlign:'left'}}>
                  <div style={{display:'flex',alignItems:'center',gap:8,flex:1,minWidth:0}}>
                    <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:isA?700:600,fontSize:isA?17:15,color:col}}>{s.name}</div>
                    {isA&&<span style={{background:getStagColor(i),borderRadius:4,padding:'1px 6px',fontFamily:"'Barlow Condensed',sans-serif",fontSize:9,fontWeight:700,color:'#fff',letterSpacing:1,flexShrink:0}}>ACTIVE</span>}
                    {isD&&<span style={{background:C.green,borderRadius:4,padding:'1px 6px',fontFamily:"'Barlow Condensed',sans-serif",fontSize:9,fontWeight:700,color:'#fff',letterSpacing:1,flexShrink:0}}>DONE</span>}
                  </div>
                  <div style={{display:'flex',alignItems:'center',gap:6,flexShrink:0}}>
                    {doingTasks.length>0&&<span style={{background:C.amber+'25',borderRadius:10,padding:'2px 7px',fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.amber}}>{doingTasks.length} active</span>}
                    {todoTasks.length>0&&<span style={{background:C.blue+'20',borderRadius:10,padding:'2px 7px',fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.blue}}>{todoTasks.length} planned</span>}
                    {s.tasks.length>0&&<span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.green}}>{doneCnt}/{s.tasks.length} ✓</span>}
                    {isD&&i===p.currentStage-1&&<button onClick={e=>{e.stopPropagation();const stages=p.stages.map((x,j)=>j===i?{...x,status:'active'}:j===i+1?{...x,status:'pending'}:x);update({...p,stages,currentStage:i});}} style={{background:'transparent',border:'1px solid '+C.purple+'60',borderRadius:5,padding:'2px 8px',cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:9,color:C.purple,letterSpacing:1}}>↩ UNDO</button>}
                    <span style={{color:C.t3,fontSize:12}}>{isExpanded?"▴":"▾"}</span>
                  </div>
                </button>
                {/* Expanded body */}
                {isExpanded&&(
                  <div style={{borderTop:'1px solid '+C.border,padding:'12px 14px'}}>
                    {(s.achievements||s.notes||s.nextSteps)&&(
                      <div style={{marginBottom:10,display:'flex',flexDirection:'column',gap:4}}>
                        {s.achievements&&<div style={{fontSize:12,color:C.green,display:'flex',gap:6}}><span>✅</span><span style={{lineHeight:1.4}}>{s.achievements}</span></div>}
                        {s.notes&&<div style={{fontSize:12,color:C.t2,display:'flex',gap:6}}><span>🔨</span><span style={{lineHeight:1.4}}>{s.notes}</span></div>}
                        {s.nextSteps&&<div style={{fontSize:12,color:C.blue,display:'flex',gap:6}}><span>⏭</span><span style={{lineHeight:1.4}}>{s.nextSteps}</span></div>}
                      </div>
                    )}
                    {s.tasks.length===0&&<div style={{color:C.t3,fontSize:12,fontStyle:'italic',textAlign:'center',padding:'8px 0'}}>No tasks for this stage — add them in the Tasks tab</div>}
                    {doingTasks.length>0&&(
                      <div style={{marginBottom:8}}>
                        <div style={{display:'flex',alignItems:'center',gap:5,marginBottom:5}}><div style={{width:6,height:6,borderRadius:'50%',background:C.amber}}/><span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.amber,letterSpacing:1}}>IN PROGRESS</span></div>
                        {doingTasks.map(t=><OvTaskRow key={t.id} t={t} sid={s.id} onMove={moveTask}/>)}
                      </div>
                    )}
                    {todoTasks.length>0&&(
                      <div style={{marginBottom:8}}>
                        <div style={{display:'flex',alignItems:'center',gap:5,marginBottom:5}}><div style={{width:6,height:6,borderRadius:'50%',background:C.blue}}/><span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.blue,letterSpacing:1}}>PLANNED</span></div>
                        {todoTasks.map(t=><OvTaskRow key={t.id} t={t} sid={s.id} onMove={moveTask}/>)}
                      </div>
                    )}
                    {doneTasks.length>0&&(
                      <div>
                        <div style={{display:'flex',alignItems:'center',gap:5,marginBottom:5}}><div style={{width:6,height:6,borderRadius:'50%',background:C.green}}/><span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.green,letterSpacing:1}}>DONE ({doneTasks.length})</span></div>
                        {doneTasks.map(t=><OvTaskRow key={t.id} t={t} sid={s.id} onMove={moveTask}/>)}
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function OvTaskRow({t,sid,onMove}) {
  const today=new Date(); today.setHours(0,0,0,0);
  const due=t.dueDate?new Date(t.dueDate):null; if(due) due.setHours(0,0,0,0);
  const overdue=due&&due<today&&t.status!=='done';
  const dueToday=due&&due.getTime()===today.getTime()&&t.status!=='done';
  return(
    <div style={{background:C.bg,border:'1px solid '+C.border,borderLeft:'3px solid '+PC[t.priority],borderRadius:7,padding:'7px 10px',marginBottom:5,display:'flex',alignItems:'center',gap:8}}>
      <div style={{flex:1,minWidth:0}}>
        <div style={{fontSize:13,color:t.status==='done'?C.t3:C.t1,textDecoration:t.status==='done'?'line-through':'none',lineHeight:1.3}}>{t.title}</div>
        {t.notes&&<div style={{fontSize:11,color:C.t3,lineHeight:1.3}}>{t.notes}</div>}
        {due&&<div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:overdue?C.red:dueToday?C.amber:C.t3,marginTop:2}}>
          {overdue?"⚠️ OVERDUE ":dueToday?"🔔 TODAY ":"📅 "}{due.toLocaleDateString('en-GB',{day:'2-digit',month:'short'})}
        </div>}
      </div>
      <div style={{display:'flex',gap:4,flexShrink:0}}>
        {t.status!=='doing'&&<button onClick={()=>onMove(sid,t.id,'doing')} style={{background:C.amber+'20',border:'1px solid '+C.amber+'50',borderRadius:5,padding:'3px 7px',cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:9,color:C.amber,whiteSpace:'nowrap'}}>▶ START</button>}
        {t.status!=='done'&&<button onClick={()=>onMove(sid,t.id,'done')} style={{background:C.green+'20',border:'1px solid '+C.green+'50',borderRadius:5,padding:'3px 7px',cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:9,color:C.green}}>✓ DONE</button>}
        {t.status!=='todo'&&<button onClick={()=>onMove(sid,t.id,'todo')} style={{background:C.blue+'20',border:'1px solid '+C.blue+'50',borderRadius:5,padding:'3px 7px',cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:9,color:C.blue}}>↩</button>}
      </div>
    </div>
  );
}

// ── TASKS TAB ────────────────────────────────────────────────────────────────
function TasksTab({p,stage,update}) {
  const [input,setInput]=useState('');const [pri,setPri]=useState('medium');const [dueDate,setDueDate]=useState('');const [openIdx,setOpenIdx]=useState(p.currentStage);const [editing,setEditing]=useState(null);const [hideDone,setHideDone]=useState(false);
  const addTask=()=>{if(!input.trim())return;const t={id:uid(),title:input.trim(),status:'todo',priority:pri,notes:'',dueDate:dueDate||null,createdAt:new Date().toISOString()};const stages=p.stages.map(s=>s.id===stage.id?{...s,tasks:[...s.tasks,t]}:s);update({...p,stages});setInput('');setDueDate('');};
  const move=(sid,tid,st)=>{const stages=p.stages.map(s=>s.id===sid?{...s,tasks:s.tasks.map(t=>t.id===tid?{...t,status:st}:t)}:s);update({...p,stages});};
  const del=(sid,tid)=>{const stages=p.stages.map(s=>s.id===sid?{...s,tasks:s.tasks.filter(t=>t.id!==tid)}:s);update({...p,stages});if(editing?.taskId===tid)setEditing(null);};
  const startEdit=(sid,t)=>setEditing({stageId:sid,taskId:t.id,title:t.title,priority:t.priority,notes:t.notes||'',dueDate:t.dueDate||''});
  const saveEdit=()=>{if(!editing||!editing.title.trim())return;const stages=p.stages.map(s=>s.id===editing.stageId?{...s,tasks:s.tasks.map(t=>t.id===editing.taskId?{...t,title:editing.title.trim(),priority:editing.priority,notes:editing.notes,dueDate:editing.dueDate||null}:t)}:s);update({...p,stages});setEditing(null);};
  const reorderTask=(sid,tid,dir)=>{
    const stages=p.stages.map(s=>{
      if(s.id!==sid) return s;
      const tasks=[...s.tasks];
      const i=tasks.findIndex(t=>t.id===tid);
      const j=i+dir;
      if(j<0||j>=tasks.length) return s;
      [tasks[i],tasks[j]]=[tasks[j],tasks[i]];
      return {...s,tasks};
    });
    update({...p,stages});
  };
  const COLS=[{id:'todo',label:'PLANNED',color:C.blue},{id:'doing',label:'IN PROGRESS',color:C.amber},{id:'done',label:'DONE',color:C.green}];const visibleCols=hideDone?COLS.filter(c=>c.id!=='done'):COLS;
  return(
    <div style={{padding:16}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:12}}>
        <Lbl style={{marginBottom:0}}>TASKS — {stage?.name?.toUpperCase()}</Lbl>
        <button onClick={()=>setHideDone(h=>!h)} style={{...BS(hideDone?C.amber:'transparent',hideDone?'#000':C.t2),padding:'5px 12px',fontSize:12,border:'1px solid '+C.border}}>
          {hideDone?'SHOW DONE':'HIDE DONE'}
        </button>
      </div>
      <div style={{background:C.card,border:'1px solid '+C.border,borderRadius:10,padding:14,marginBottom:18}}>
        <Lbl style={{marginBottom:10}}>ADD TASK — {stage?.name?.toUpperCase()}</Lbl>
        <div style={{display:'flex',gap:8,marginBottom:10}}>
          <input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==='Enter'&&addTask()} placeholder="Describe the task..." style={IS({flex:1})}/>
          <button onClick={addTask} style={{...BS(C.amber),padding:'10px 16px'}}>ADD</button>
        </div>
        <div style={{display:'flex',gap:8,alignItems:'center',flexWrap:'wrap'}}>
          {['high','medium','low'].map(pr=>(
            <button key={pr} onClick={()=>setPri(pr)} style={{padding:'4px 12px',borderRadius:20,border:'1px solid '+PC[pr],background:pri===pr?PC[pr]+'25':'transparent',color:PC[pr],cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:11,letterSpacing:1}}>{pr.toUpperCase()}</button>
          ))}
          <div style={{display:'flex',alignItems:'center',gap:6,marginLeft:'auto'}}>
            <label style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3,whiteSpace:'nowrap'}}>📅 DUE</label>
            <input type="date" value={dueDate} onChange={e=>setDueDate(e.target.value)} style={{background:C.bg,border:'1px solid '+C.border,borderRadius:6,padding:'4px 8px',color:C.t1,fontFamily:"'Barlow',sans-serif",fontSize:12,outline:'none'}}/>
          </div>
        </div>
      </div>
      {p.stages.filter((_,i)=>i<=p.currentStage).map((s,si)=>{
        if(s.tasks.length===0&&si!==p.currentStage)return null;
        const isOpen=openIdx===si;
        return(
          <div key={s.id} style={{marginBottom:18}}>
            <button onClick={()=>setOpenIdx(isOpen?-1:si)} style={{width:'100%',background:'transparent',border:'none',cursor:'pointer',textAlign:'left',padding:'7px 0',display:'flex',justifyContent:'space-between',alignItems:'center'}}>
              <div style={{display:'flex',alignItems:'center',gap:8}}>
                <Lbl style={{marginBottom:0}}>STAGE {si+1} — {s.name.toUpperCase()}</Lbl>
                {si===p.currentStage&&<span style={{background:C.amber,borderRadius:4,padding:'1px 6px',fontFamily:"'Barlow Condensed',sans-serif",fontSize:9,fontWeight:700,color:'#000'}}>ACTIVE</span>}
              </div>
              <span style={{color:C.t3,fontSize:14}}>{isOpen?"▴":"▾"}</span>
            </button>
            {isOpen&&(
              <>
                {s.tasks.length===0&&<div style={{color:C.t3,fontSize:13,padding:'6px 0',fontStyle:'italic'}}>No tasks yet</div>}
                {visibleCols.map(col=>{const ct=s.tasks.filter(t=>t.status===col.id);if(!ct.length)return null;return(
                  <div key={col.id} style={{marginBottom:10}}>
                    <div style={{display:'flex',alignItems:'center',gap:6,marginBottom:7}}>
                      <div style={{width:7,height:7,borderRadius:'50%',background:col.color}}/>
                      <span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:col.color,letterSpacing:1}}>{col.label}</span>
                      <span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.t3,background:C.border,borderRadius:10,padding:'0 6px'}}>{ct.length}</span>
                    </div>
                    {ct.map(task=>{
                      const isEd=editing?.taskId===task.id;
                      const taskIdx=s.tasks.findIndex(t=>t.id===task.id);
                      const sameStatusTasks=s.tasks.filter(t=>t.status===col.id);
                      const posInGroup=sameStatusTasks.findIndex(t=>t.id===task.id);
                      return(
                      <div key={task.id} style={{background:isEd?C.surface:C.card,border:'1px solid '+(isEd?C.amber:C.border),borderLeft:'3px solid '+PC[isEd?editing.priority:task.priority],borderRadius:8,padding:'10px 12px',marginBottom:8}}>
                        {isEd?(
                          <>
                            <input value={editing.title} onChange={e=>setEditing(ed=>({...ed,title:e.target.value}))} autoFocus style={IS({marginBottom:8})}/>
                            <textarea value={editing.notes} onChange={e=>setEditing(ed=>({...ed,notes:e.target.value}))} placeholder="Notes..." rows={2} style={IS({resize:'vertical',lineHeight:1.5,marginBottom:8})}/>
                            <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:8}}>
                              <label style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3,whiteSpace:'nowrap'}}>📅 DUE DATE</label>
                              <input type="date" value={editing.dueDate||''} onChange={e=>setEditing(ed=>({...ed,dueDate:e.target.value}))} style={{background:C.bg,border:'1px solid '+C.border,borderRadius:6,padding:'6px 10px',color:C.t1,fontFamily:"'Barlow',sans-serif",fontSize:13,outline:'none',flex:1}}/>
                              {editing.dueDate&&<button onClick={()=>setEditing(ed=>({...ed,dueDate:''}))} style={{background:'transparent',border:'none',color:C.t3,cursor:'pointer',fontSize:16}}>×</button>}
                            </div>
                            <div style={{display:'flex',gap:6,marginBottom:10,alignItems:'center'}}>
                              <span style={{fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:C.t3}}>PRIORITY:</span>
                              {['high','medium','low'].map(pr=>(
                                <button key={pr} onClick={()=>setEditing(ed=>({...ed,priority:pr}))} style={{padding:'3px 10px',borderRadius:20,border:'1px solid '+PC[pr],background:editing.priority===pr?PC[pr]+'30':'transparent',color:PC[pr],cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:10}}>{pr.toUpperCase()}</button>
                              ))}
                            </div>
                            <div style={{display:'flex',gap:8}}>
                              <button onClick={()=>setEditing(null)} style={{...BS('transparent',C.t2),flex:1,border:'1px solid '+C.border,padding:'8px'}}>CANCEL</button>
                              <button onClick={saveEdit} style={{...BS(C.amber),flex:2,padding:'8px'}}>SAVE CHANGES</button>
                            </div>
                          </>
                        ):(
                          <>
                            <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:8}}>
                              <div style={{flex:1}}><div style={{fontSize:14,color:C.t1}}>{task.title}</div>{task.notes&&<div style={{fontSize:12,color:C.t3,marginTop:3,lineHeight:1.4}}>{task.notes}</div>}</div>
                              <div style={{display:'flex',gap:2,flexShrink:0,alignItems:'center'}}>
                                {/* Up/Down reorder within stage */}
                                <button
                                  onClick={()=>reorderTask(s.id,task.id,-1)}
                                  disabled={taskIdx===0}
                                  title="Move up"
                                  style={{background:'transparent',border:'1px solid '+C.border,borderRadius:5,cursor:taskIdx===0?'default':'pointer',width:24,height:24,color:taskIdx===0?C.border:C.t2,display:'flex',alignItems:'center',justifyContent:'center',fontSize:10,flexShrink:0}}>▲</button>
                                <button
                                  onClick={()=>reorderTask(s.id,task.id,1)}
                                  disabled={taskIdx>=s.tasks.length-1}
                                  title="Move down"
                                  style={{background:'transparent',border:'1px solid '+C.border,borderRadius:5,cursor:taskIdx>=s.tasks.length-1?'default':'pointer',width:24,height:24,color:taskIdx>=s.tasks.length-1?C.border:C.t2,display:'flex',alignItems:'center',justifyContent:'center',fontSize:10,flexShrink:0}}>▼</button>
                                <button onClick={()=>startEdit(s.id,task)} style={{background:'transparent',border:'none',cursor:'pointer',fontSize:14,padding:'2px 4px'}}>✏️</button>
                                <button onClick={()=>del(s.id,task.id)} style={{background:'transparent',border:'none',color:C.t3,cursor:'pointer',fontSize:18,lineHeight:1,padding:0}}>×</button>
                              </div>
                            </div>
                            <div style={{display:'flex',gap:6,marginTop:8,flexWrap:'wrap'}}>
                              {col.id!=='todo'&&<Chip color={C.blue} onClick={()=>move(s.id,task.id,'todo')}>↩ PLANNED</Chip>}
                              {col.id!=='doing'&&<Chip color={C.amber} onClick={()=>move(s.id,task.id,'doing')}>⏳ IN PROGRESS</Chip>}
                              {col.id!=='done'&&<Chip color={C.green} onClick={()=>move(s.id,task.id,'done')}>✓ DONE</Chip>}
                            </div>
                          </>
                        )}
                      </div>
                    );})}
                  </div>
                );})}
              </>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ── PHOTOS TAB ───────────────────────────────────────────────────────────────
function PhotosTab({projectId,stage,profile}) {
  const [photos,setPhotos]=useState([]);
  const [archived,setArchived]=useState([]);
  const [loading,setLoading]=useState(true);
  const [lb,setLb]=useState(null);
  const [showArchived,setShowArchived]=useState(false);
  const fileRef=useRef();
  const isAdmin=profile?.role==='admin'||profile?.role==='superadmin'||profile?.role==='super_admin';

  const load=()=>{
    if(!stage)return;
    setLoading(true);
    dbPhotos(projectId)
      .then(rows=>{setPhotos(rows.filter(r=>r.stage_id===stage.id));setLoading(false);})
      .catch(()=>setLoading(false));
  };
  const loadArchived=()=>{
    dbArchivedPhotos(projectId)
      .then(rows=>setArchived(rows.filter(r=>r.stage_id===stage.id)))
      .catch(()=>{});
  };

  useEffect(()=>{load();},[projectId,stage?.id]);
  useEffect(()=>{if(showArchived)loadArchived();},[showArchived,stage?.id]);

  const upload=e=>{Array.from(e.target.files||[]).forEach(file=>{const r=new FileReader();r.onload=ev=>{const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');const maxW=1200,scale=img.width>maxW?maxW/img.width:1;canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const photo={id:uid(),project_id:projectId,stage_id:stage.id,data_url:canvas.toDataURL('image/jpeg',0.7),caption:'',taken_at:new Date().toISOString(),archived:false};setPhotos(prev=>[...prev,photo]);dbAddPhoto(photo).catch(()=>{});};img.src=ev.target.result;};r.readAsDataURL(file);});e.target.value='';};
  const setCaption=(id,caption)=>{setPhotos(prev=>prev.map(ph=>ph.id===id?{...ph,caption}:ph));dbCaption(id,caption).catch(()=>{});};
  const archivePhoto=(id)=>{
    setPhotos(prev=>prev.filter(ph=>ph.id!==id));
    dbArchivePhoto(id,true).catch(()=>{});
    if(lb?.id===id) setLb(null);
  };
  const restorePhoto=(id)=>{
    setArchived(prev=>prev.filter(ph=>ph.id!==id));
    dbArchivePhoto(id,false).then(()=>load()).catch(()=>{});
  };
  const delPhoto=(id)=>{
    setPhotos(prev=>prev.filter(ph=>ph.id!==id));
    dbDelPhoto(id).catch(()=>{});
    if(lb?.id===id) setLb(null);
  };

  if(loading) return <div style={{textAlign:'center',padding:'60px 0',color:C.t3}}>Loading photos…</div>;

  return(
    <div style={{padding:16}}>
      <Lbl>PHOTOS — {stage?.name?.toUpperCase()}</Lbl>
      <input type="file" accept="image/*" multiple ref={fileRef} onChange={upload} style={{display:'none'}}/>
      <button onClick={()=>fileRef.current?.click()} style={{width:'100%',background:C.card,border:'2px dashed '+C.amber+'70',borderRadius:10,padding:'18px',cursor:'pointer',color:C.amber,fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:15,letterSpacing:1,marginBottom:16,display:'flex',alignItems:'center',justifyContent:'center',gap:10}}>📷 UPLOAD SITE PHOTOS</button>

      {!photos.length&&<div style={{textAlign:'center',padding:'40px 0',color:C.t3}}>No photos for this stage yet</div>}

      <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(180px,1fr))',gap:12,marginBottom:16}}>
        {photos.map(ph=>(
          <div key={ph.id} style={{background:C.card,border:'1px solid '+C.border,borderRadius:10,overflow:'hidden'}}>
            <div style={{position:'relative',cursor:'pointer'}} onClick={()=>setLb(ph)}>
              <img src={ph.data_url} alt="" style={{width:'100%',height:150,objectFit:'cover',display:'block'}}/>
              {isAdmin&&(
                <button onClick={e=>{e.stopPropagation();archivePhoto(ph.id);}}
                  title="Archive photo"
                  style={{position:'absolute',top:6,right:6,background:'#000b',border:'none',borderRadius:6,padding:'3px 8px',color:'#fff',cursor:'pointer',fontSize:11,fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,display:'flex',alignItems:'center',gap:3}}>
                  📦 ARCHIVE
                </button>
              )}
              <div style={{position:'absolute',bottom:6,left:6,fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:'#fff',background:'#000a',borderRadius:3,padding:'2px 6px'}}>{new Date(ph.taken_at).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'2-digit'})}</div>
            </div>
            <div style={{padding:'8px 10px'}}><input value={ph.caption} onChange={e=>setCaption(ph.id,e.target.value)} placeholder="Add caption..." style={{width:'100%',background:'transparent',border:'none',color:C.t2,fontFamily:"'Barlow',sans-serif",fontSize:12,outline:'none',padding:0}}/></div>
          </div>
        ))}
      </div>

      {isAdmin&&(
        <button onClick={()=>setShowArchived(v=>!v)}
          style={{background:C.card,border:'1px solid '+C.border,borderRadius:8,padding:'8px 16px',cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:13,color:C.t2,marginBottom:12,display:'flex',alignItems:'center',gap:6}}>
          📦 {showArchived?'HIDE':'SHOW'} ARCHIVED PHOTOS {archived.length>0&&!showArchived&&<span style={{background:C.border,borderRadius:10,padding:'1px 7px',fontSize:11}}>{archived.length}</span>}
        </button>
      )}

      {isAdmin&&showArchived&&(
        <div>
          <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3,letterSpacing:1,marginBottom:10}}>ARCHIVED ({archived.length})</div>
          {archived.length===0&&<div style={{color:C.t3,fontSize:13,marginBottom:16}}>No archived photos for this stage.</div>}
          <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(180px,1fr))',gap:12,marginBottom:16}}>
            {archived.map(ph=>(
              <div key={ph.id} style={{background:C.card,border:'1px solid '+C.border,borderRadius:10,overflow:'hidden',opacity:0.75}}>
                <div style={{position:'relative'}}>
                  <img src={ph.data_url} alt="" style={{width:'100%',height:150,objectFit:'cover',display:'block',filter:'grayscale(30%)'}}/>
                  <div style={{position:'absolute',inset:0,background:'#0004',display:'flex',alignItems:'flex-start',justifyContent:'flex-end',padding:6,gap:4}}>
                    <button onClick={()=>restorePhoto(ph.id)}
                      style={{background:C.green,border:'none',borderRadius:6,padding:'3px 8px',color:'#fff',cursor:'pointer',fontSize:11,fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700}}>
                      ↩ RESTORE
                    </button>
                    <button onClick={()=>delPhoto(ph.id)}
                      style={{background:'#DC2626',border:'none',borderRadius:6,padding:'3px 8px',color:'#fff',cursor:'pointer',fontSize:11,fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700}}>
                      🗑 DELETE
                    </button>
                  </div>
                  <div style={{position:'absolute',bottom:6,left:6,fontFamily:"'JetBrains Mono',monospace",fontSize:9,color:'#fff',background:'#000a',borderRadius:3,padding:'2px 6px'}}>{new Date(ph.taken_at).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'2-digit'})}</div>
                </div>
                {ph.caption&&<div style={{padding:'6px 10px',fontSize:11,color:C.t3}}>{ph.caption}</div>}
              </div>
            ))}
          </div>
        </div>
      )}

      {lb&&(
        <div onClick={()=>setLb(null)} style={{position:'fixed',inset:0,background:'#000e',display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',zIndex:999,padding:20}}>
          <img src={lb.data_url} alt="" style={{maxWidth:'100%',maxHeight:'75vh',borderRadius:8,objectFit:'contain'}} onClick={e=>e.stopPropagation()}/>
          {lb.caption&&<div style={{marginTop:12,color:'#fff',fontSize:14}}>{lb.caption}</div>}
          <div style={{display:'flex',gap:10,marginTop:16}}>
            {isAdmin&&<button onClick={e=>{e.stopPropagation();archivePhoto(lb.id);}} style={{...BS('#64748B'),padding:'10px 20px',fontSize:13}}>📦 ARCHIVE</button>}
            <button onClick={()=>setLb(null)} style={{...BS(C.amber),padding:'10px 28px'}}>CLOSE</button>
          </div>
        </div>
      )}
    </div>
  );
}
function NotesTab({p,stage,update,user}) {
  const [local,setLocal]=useState({notes:stage.notes,achievements:stage.achievements,nextSteps:stage.nextSteps});const [saved,setSaved]=useState(true);
  useEffect(()=>{setLocal({notes:stage.notes,achievements:stage.achievements,nextSteps:stage.nextSteps});setSaved(true);},[stage.id]);
  const change=k=>e=>{setLocal(l=>({...l,[k]:e.target.value}));setSaved(false);};
  const save=()=>{
    const now=new Date().toISOString();
    const stages=p.stages.map(s=>s.id===stage.id?{...s,...local,notedAt:now,notedBy:user?.email||''}:s);
    update({...p,stages});
    setSaved(true);
    // Browser notification for admin awareness
    try{if('Notification' in window&&Notification.permission==='granted'){new Notification("📝 Site Notes Updated",{body:p.name+' — '+stage.name,tag:'note-'+stage.id,icon:'/favicon.ico'});}}catch(e){}
  };
  const FIELDS=[{k:'achievements',icon:"✅",label:"WHAT'S BEEN ACHIEVED",ph:'Completed work, milestones...'},{k:'notes',icon:'🔨',label:'WORK CURRENTLY UNDERWAY',ph:'Active construction activities...'},{k:'nextSteps',icon:'⏭',label:'NEXT SCHEDULED STEPS',ph:'Upcoming tasks, deliveries...'}];
  return(
    <div style={{padding:16}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:20}}>
        <Lbl style={{marginBottom:0}}>SITE NOTES — {stage?.name?.toUpperCase()}</Lbl>
        <button onClick={save} style={{...BS(saved?C.border:C.amber,saved?C.t3:'#000'),padding:'8px 20px',transition:'all 0.2s'}}>{saved?"SAVED ✓":'SAVE NOTES'}</button>
      </div>
      {FIELDS.map(({k,icon,label,ph})=>(
        <div key={k} style={{marginBottom:20}}><label style={{...LS,marginBottom:8}}>{icon} {label}</label><textarea value={local[k]} onChange={change(k)} placeholder={ph} style={IS({resize:'vertical',minHeight:100,lineHeight:1.6})}/></div>
      ))}
    </div>
  );
}

// ── TEAM TAB ─────────────────────────────────────────────────────────────────
function TeamTab({p,update}) {
  const sups=p.supervisors||[];const [showForm,setShowForm]=useState(false);const [editId,setEditId]=useState(null);const [form,setForm]=useState({name:'',role:'Site Supervisor',phone:'',email:'',notes:''});
  const blank={name:'',role:'Site Supervisor',phone:'',email:'',notes:''};
  const openAdd=()=>{setForm(blank);setEditId(null);setShowForm(true);};const openEdit=s=>{setForm({name:s.name,role:s.role,phone:s.phone||'',email:s.email||'',notes:s.notes||''});setEditId(s.id);setShowForm(true);};const close=()=>{setShowForm(false);setEditId(null);};
  const setF=k=>e=>setForm(f=>({...f,[k]:e.target.value}));
  const saveSup=()=>{if(!form.name.trim())return;const updated=editId?sups.map(s=>s.id===editId?{...s,...form,name:form.name.trim()}:s):[...sups,{id:uid(),...form,name:form.name.trim(),addedAt:new Date().toISOString()}];update({...p,supervisors:updated});close();};
  const rem=id=>update({...p,supervisors:sups.filter(s=>s.id!==id)});
  return(
    <div style={{padding:16}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:18}}>
        <div><Lbl style={{marginBottom:2}}>PROJECT TEAM</Lbl><div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3}}>{sups.length} member{sups.length!==1?'s':''}</div></div>
        <button onClick={openAdd} style={{...BS(C.amber),padding:'9px 16px'}}>+ ADD MEMBER</button>
      </div>
      {showForm&&(
        <div style={{background:C.surface,border:'1px solid '+C.amber,borderRadius:12,padding:20,marginBottom:20}}>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:20,letterSpacing:1,marginBottom:16}}>{editId?'EDIT MEMBER':'ADD MEMBER'}</div>
          <label style={LS}>FULL NAME *</label><input value={form.name} onChange={setF('name')} placeholder="e.g. James O'Brien" style={IS({marginBottom:14})}/>
          <label style={LS}>ROLE</label><select value={form.role} onChange={setF('role')} style={IS({marginBottom:14,cursor:'pointer'})}>{ROLES.map(r=><option key={r} value={r}>{r}</option>)}</select>
          <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:14,marginBottom:14}}>
            <div><label style={LS}>PHONE</label><input value={form.phone} onChange={setF('phone')} type="tel" placeholder="+44 7700 900000" style={IS()}/></div>
            <div><label style={LS}>EMAIL</label><input value={form.email} onChange={setF('email')} type="email" placeholder="name@co.com" style={IS()}/></div>
          </div>
          <label style={LS}>NOTES / RESPONSIBILITIES</label>
          <textarea value={form.notes} onChange={setF('notes')} placeholder="Responsible for..." rows={2} style={IS({resize:'vertical',lineHeight:1.5,marginBottom:16})}/>
          <div style={{display:'flex',gap:10}}>
            <button onClick={close} style={{...BS('transparent',C.t2),flex:1,border:'1px solid '+C.border,padding:'11px'}}>CANCEL</button>
            <button onClick={saveSup} style={{...BS(C.amber),flex:2,padding:'11px'}}>{editId?'SAVE CHANGES':'ADD TO PROJECT'}</button>
          </div>
        </div>
      )}
      {sups.length===0&&!showForm&&<div style={{textAlign:'center',padding:'50px 0',color:C.t3}}><div style={{fontSize:48,marginBottom:14}}>👷</div><div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:22,color:C.t2,marginBottom:8}}>NO TEAM MEMBERS YET</div></div>}
      {sups.map(s=>{const rc=ROLE_C[s.role]||C.t3;const ini=s.name.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();return(
        <div key={s.id} style={{background:C.card,border:'1px solid '+C.border,borderRadius:12,padding:16,marginBottom:12,display:'flex',gap:14,alignItems:'flex-start'}}>
          <div style={{width:44,height:44,borderRadius:'50%',background:rc+'20',border:'2px solid '+rc,display:'flex',alignItems:'center',justifyContent:'center',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:16,color:rc,flexShrink:0}}>{ini}</div>
          <div style={{flex:1,minWidth:0}}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:8,marginBottom:5}}>
              <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:19}}>{s.name}</div>
              <div style={{display:'flex',gap:6,flexShrink:0}}>
                <button onClick={()=>openEdit(s)} style={{background:'transparent',border:'none',cursor:'pointer',fontSize:14,padding:'2px 4px'}}>✏️</button>
                <button onClick={()=>rem(s.id)} style={{background:'transparent',border:'none',color:C.t3,cursor:'pointer',fontSize:20,lineHeight:1,padding:0}}>×</button>
              </div>
            </div>
            <div style={{display:'inline-block',background:rc+'20',border:'1px solid '+rc+'50',borderRadius:5,padding:'2px 10px',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:11,letterSpacing:1,color:rc,marginBottom:8}}>{s.role.toUpperCase()}</div>
            <div style={{display:'flex',flexWrap:'wrap',gap:'5px 16px'}}>
              {s.phone&&<a href={'tel:'+s.phone} style={{fontFamily:"'JetBrains Mono',monospace",fontSize:11,color:C.blue,textDecoration:'none'}}>📞 {s.phone}</a>}
              {s.email&&<a href={'mailto:'+s.email} style={{fontFamily:"'JetBrains Mono',monospace",fontSize:11,color:C.blue,textDecoration:'none'}}>✉️ {s.email}</a>}
            </div>
            {s.notes&&<div style={{fontSize:13,color:C.t3,marginTop:7,lineHeight:1.4}}>{s.notes}</div>}
          </div>
        </div>
      );})}
    </div>
  );
}

