// ── BUILD ACTIVITY FEED ───────────────────────────────────────────────────────
function buildReminders(projects){
  const items=[];
  const today=new Date(); today.setHours(0,0,0,0);
  const in7=new Date(today); in7.setDate(in7.getDate()+7);
  projects.forEach(p=>{
    p.stages.forEach(s=>{
      (s.tasks||[]).forEach(t=>{
        if(t.status==='done') return; // skip done tasks in reminders
        if(t.dueDate){
          const due=new Date(t.dueDate); due.setHours(0,0,0,0);
          const overdue=due<today;
          const dueToday=due.getTime()===today.getTime();
          const upcoming=due>today&&due<=in7;
          if(overdue) items.push({type:'overdue',icon:"⚠️",color:'#DC2626',title:'OVERDUE',desc:t.title,project:p.name+' — '+s.name,id:'ov'+t.id,dueDate:t.dueDate,task:t,stage:s,proj:p});
          else if(dueToday) items.push({type:'duetoday',icon:"🔔",color:'#DC2626',title:'DUE TODAY',desc:t.title,project:p.name+' — '+s.name,id:'dt'+t.id,dueDate:t.dueDate,task:t,stage:s,proj:p});
          else if(upcoming) items.push({type:'upcoming',icon:"📅",color:'#B8960C',title:'Due '+new Date(t.dueDate).toLocaleDateString('en-GB',{day:'2-digit',month:'short'}),desc:t.title,project:p.name+' — '+s.name,id:'up'+t.id,dueDate:t.dueDate,task:t,stage:s,proj:p});
        }
        if(t.status==='doing') items.push({type:'doing',icon:"⏳",color:'#0284C7',title:'IN PROGRESS',desc:t.title,project:p.name+' — '+s.name,id:'do'+t.id,task:t,stage:s,proj:p});
      });
    });
  });
  const order={overdue:0,duetoday:1,upcoming:2,doing:3};
  return items.sort((a,b)=>(order[a.type]||9)-(order[b.type]||9)).slice(0,30);
}

function buildNotes(projects){
  const items=[];
  projects.forEach(p=>{
    p.stages.forEach((s,i)=>{
      if(s.status==='complete') items.push({type:'stage',icon:"🏆",color:'#059669',title:'Stage Complete',desc:s.name,project:p.name,id:'st'+p.id+i});
      if(s.achievements) items.push({type:'note',icon:"✅",color:'#059669',title:'Achievement',desc:s.achievements.slice(0,100),project:p.name+' — '+s.name,id:'ach'+p.id+i});
      if(s.notes) items.push({type:'note',icon:"📝",color:'#7C3AED',title:'Site Notes',desc:s.notes.slice(0,100),project:p.name+' — '+s.name,id:'nt'+p.id+i});
      if(s.nextSteps) items.push({type:'note',icon:"⏭",color:'#B8960C',title:'Next Steps',desc:s.nextSteps.slice(0,100),project:p.name+' — '+s.name,id:'ns'+p.id+i});
      (s.tasks||[]).filter(t=>t.status==='done').forEach(t=>{
        items.push({type:'done',icon:"✓",color:'#059669',title:'Task Done',desc:t.title,project:p.name+' — '+s.name,id:'td'+t.id});
      });
    });
  });
  return items.slice(0,40);
}

// ── SHARED SCROLL STRIP ───────────────────────────────────────────────────────
function ScrollStrip({items,onAction,onDismiss,emptyMsg}) {
  if(!items.length) return(
    <div style={{background:C.surface,border:'1px solid '+C.border,borderRadius:10,padding:'14px 16px',color:C.t3,fontSize:13,fontStyle:'italic'}}>{emptyMsg}</div>
  );
  return(
    <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(280px,1fr))',gap:10}}>
      {items.filter(item=>item&&item.id).map(item=>{
        const clickable=!!onAction&&!!(item.task&&item.stage&&item.proj);
        const priority=item.task?.priority;
        const priBg=priority==='high'||priority==='HIGH'?'#FEE2E2':priority==='medium'||priority==='MED'?'#FEF3C7':'#F0FDF4';
        const priColor=priority==='high'||priority==='HIGH'?'#DC2626':priority==='medium'||priority==='MED'?'#B8960C':'#16A34A';
        const priLabel=priority?priority.toUpperCase():null;
        return(
          <div key={item.id}
            onClick={()=>clickable&&onAction(item)}
            style={{background:'#fff',border:'1px solid '+C.border,borderLeft:'4px solid '+item.color,borderRadius:12,padding:'14px 16px',cursor:clickable?'pointer':'default',position:'relative',boxShadow:'0 1px 4px rgba(0,0,0,0.05)',transition:'box-shadow 0.15s'}}
            onMouseEnter={e=>{if(clickable)e.currentTarget.style.boxShadow='0 4px 16px rgba(0,0,0,0.1)';}}
            onMouseLeave={e=>{e.currentTarget.style.boxShadow='0 1px 4px rgba(0,0,0,0.05)';}}
          >
            {onDismiss&&<button onClick={e=>{e.stopPropagation();onDismiss(item.id);}} style={{position:'absolute',top:8,right:10,background:'transparent',border:'none',color:C.t3,cursor:'pointer',fontSize:16,padding:0,lineHeight:1}} onMouseEnter={e=>e.currentTarget.style.color='#DC2626'} onMouseLeave={e=>e.currentTarget.style.color=C.t3}>{"×"}</button>}
            <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:8}}>
              <span style={{fontSize:20}}>{item.icon}</span>
              <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:12,color:item.color,letterSpacing:1}}>{item.title}</div>
              {priLabel&&<div style={{background:priBg,border:'1px solid '+priColor+'40',borderRadius:5,padding:'2px 8px',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:10,color:priColor,marginLeft:'auto',marginRight:onDismiss?20:0}}>{priLabel}</div>}
            </div>
            <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:18,color:C.t1,marginBottom:4,lineHeight:1.2}}>{item.desc}</div>
            {item.dueDate&&<div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:item.color,marginBottom:4}}>{"DUE: "}{new Date(item.dueDate).toLocaleDateString('en-AU',{weekday:'short',day:'numeric',month:'short'})}</div>}
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginTop:6}}>
              <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3}}>{"📁 "}{item.project}</div>
              {clickable&&<div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:11,color:item.color,letterSpacing:0.5}}>{"TAP TO UPDATE →"}</div>}
            </div>
          </div>
        );
      })}
    </div>
  );
}
function SafeActivityFeed({projects,onSave}) {
  try {
    return <ActivityFeed projects={projects} onSave={onSave}/>;
  } catch(e) {
    console.error('ActivityFeed error:',e);
    return null;
  }
}

function ActivityFeed({projects,onSave}) {
  useNotifications(projects);
  const reminders=buildReminders(projects);
  const notes=buildNotes(projects);
  const [quickAction,setQuickAction]=useState(null);
  const [dismissedReminders,setDismissedReminders]=useState(()=>{try{return JSON.parse(localStorage.getItem('ph_dismissed_r')||'[]');}catch{return [];}});
  // Notes dismissals are session-only - don't persist between page loads
  const [dismissedNotes,setDismissedNotes]=useState([]);

  const dismiss=(id)=>{
    // Check if it's a reminder or note
    if(reminders.find(r=>r.id===id)){
      const next=[...dismissedReminders,id];
      setDismissedReminders(next);
      try{localStorage.setItem('ph_dismissed_r',JSON.stringify(next));}catch{}
    } else {
      setDismissedNotes(prev=>[...prev,id]);
    }
  };
  const clearDismissed=()=>{
    setDismissedReminders([]);
    setDismissedNotes([]);
    try{localStorage.removeItem('ph_dismissed_r');}catch{}
  };

  const visibleReminders=reminders.filter(r=>!dismissedReminders.includes(r.id)).slice(0,12);
  const hiddenCount=reminders.length-visibleReminders.length;
  const visibleNotes=notes.filter(n=>!dismissedNotes.includes(n.id)).slice(0,8);
  const hiddenNotes=dismissedNotes.length;

  const openAction=(item)=>{
    if(item.task&&item.stage&&item.proj) setQuickAction({task:item.task,stage:item.stage,project:item.proj,item});
  };

  // Clear old dismissed notes from localStorage (migration)
  useEffect(()=>{try{localStorage.removeItem('ph_dismissed');}catch{}}, []);

  const updateTaskStatus=(status)=>{
    if(!quickAction||!onSave) return;
    const {project,stage,task}=quickAction;
    const stages=project.stages.map(s=>s.id===stage.id?{...s,tasks:s.tasks.map(t=>t.id===task.id?{...t,status}:t)}:s);
    onSave({...project,stages});
    // auto-dismiss the notification when marking done
    if(status==='done') dismiss(quickAction.item.id);
    setQuickAction(null);
  };

  return(
    <div style={{marginBottom:20}}>
      {/* Strip 1 — Reminders & Tasks */}
      <div style={{marginBottom:16}}>
        <div style={{display:'flex',alignItems:'center',gap:10,marginBottom:12}}>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:16,letterSpacing:1,color:C.t1}}>{"🔔 REMINDERS & TASKS"}</div>
          {visibleReminders.length>0&&<div style={{background:'#FEE2E2',border:'1px solid #FCA5A5',borderRadius:20,padding:'2px 10px',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:12,color:'#DC2626'}}>{visibleReminders.length}</div>}
          {hiddenCount>0&&<button onClick={clearDismissed} style={{background:'transparent',border:'1px solid '+C.border,borderRadius:8,padding:'3px 10px',fontSize:11,color:C.t3,cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,marginLeft:'auto'}}>{"↩ "+hiddenCount+" DISMISSED"}</button>}
        </div>
        <ScrollStrip items={visibleReminders} onAction={openAction} onDismiss={dismiss} emptyMsg={"No overdue tasks or upcoming deadlines — all clear! ✓"}/>
      </div>

      {/* Strip 2 — Notes & Activity */}
      <div>
        <div style={{display:'flex',alignItems:'center',gap:10,marginBottom:12,marginTop:20}}>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:16,letterSpacing:1,color:C.t1}}>{"📝 RECENT NOTES & ACTIVITY"}</div>
          {visibleNotes.length>0&&<div style={{background:'#EDE9FE',border:'1px solid #C4B5FD',borderRadius:20,padding:'2px 10px',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:12,color:'#7C3AED'}}>{visibleNotes.length}</div>}
          {hiddenNotes>0&&<button onClick={clearDismissed} style={{background:'transparent',border:'1px solid '+C.border,borderRadius:8,padding:'3px 10px',fontSize:11,color:C.t3,cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,marginLeft:'auto'}}>{"↩ "+hiddenNotes+" HIDDEN"}</button>}
        </div>
        <ScrollStrip items={visibleNotes} onAction={null} onDismiss={dismiss} emptyMsg={"No notes logged yet — add achievements and site notes to see them here"}/>
      </div>

      {/* Quick Action Modal */}
      {quickAction&&(
        <div onClick={()=>setQuickAction(null)} style={{position:'fixed',inset:0,background:'#0008',display:'flex',alignItems:'center',justifyContent:'center',zIndex:999,padding:20}}>
          <div onClick={e=>e.stopPropagation()} style={{background:C.surface,borderRadius:16,padding:24,maxWidth:380,width:'100%',boxShadow:'0 20px 60px rgba(0,0,0,0.3)'}}>
            <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:20,color:C.t1,marginBottom:4}}>{quickAction.task.title}</div>
            <div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:10,color:C.t3,marginBottom:4}}>{quickAction.project.name} — {quickAction.stage.name}</div>
            {quickAction.task.priority&&(
              <div style={{display:'inline-block',background:quickAction.task.priority==='HIGH'?'#FEE2E2':quickAction.task.priority==='MED'?'#FEF3C7':'#F0FDF4',border:'1px solid '+(quickAction.task.priority==='HIGH'?'#FCA5A5':quickAction.task.priority==='MED'?'#FCD34D':'#86EFAC'),borderRadius:6,padding:'2px 10px',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:12,color:quickAction.task.priority==='HIGH'?'#DC2626':quickAction.task.priority==='MED'?'#B8960C':'#16A34A',marginBottom:16}}>
                {quickAction.task.priority==='HIGH'?"🔴":quickAction.task.priority==='MED'?"🟡":"🟢"} {quickAction.task.priority} PRIORITY
              </div>
            )}
            {quickAction.task.dueDate&&<div style={{fontFamily:"'JetBrains Mono',monospace",fontSize:11,color:C.amber,marginBottom:16}}>DUE: {new Date(quickAction.task.dueDate).toLocaleDateString('en-AU',{weekday:'long',day:'numeric',month:'long'})}</div>}
            <div style={{display:'flex',gap:8,flexWrap:'wrap'}}>
              <button onClick={()=>updateTaskStatus('doing')} style={{...BS(C.blue),padding:'8px 14px',fontSize:13,flex:1}}>{"▶ START"}</button>
              <button onClick={()=>updateTaskStatus('done')} style={{...BS(C.green),padding:'8px 14px',fontSize:13,flex:1}}>{"✓ MARK DONE"}</button>
            </div>
            <button onClick={()=>{dismiss(quickAction.item.id);setQuickAction(null);}} style={{width:'100%',marginTop:8,background:'transparent',border:'1px solid '+C.border,borderRadius:8,padding:'7px',color:C.t3,cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:12}}>{"📦 DISMISS NOTIFICATION"}</button>
            <button onClick={()=>setQuickAction(null)} style={{width:'100%',marginTop:6,background:'transparent',border:'none',color:C.t3,cursor:'pointer',fontSize:12,padding:'4px'}}>CANCEL</button>
          </div>
        </div>
      )}
    </div>
  );
}
function FilesTab({ p, update }) {
  const files = p.projectFiles || [];
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({ name:'', url:'', category:'architectural', description:'' });
  const [uploadFile, setUploadFile] = useState(null);
  const fileRef = useRef();
  const blank = { name:'', url:'', category:'architectural', description:'' };

  const openAdd = (catId='architectural') => { setForm({ ...blank, category:catId }); setEditing('new'); };
  const openEdit = (f) => { setForm({ name:f.name, url:f.url||'', category:f.category||'architectural', description:f.description||'' }); setEditing(f.id); };
  const close = () => { setEditing(null); setUploadFile(null); };
  const setF = k => e => setForm(f=>({...f,[k]:e.target.value}));

  const handleFileUpload = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { alert('File too large — max 5MB. Use Google Drive for larger files.'); return; }
    const reader = new FileReader();
    reader.onload = ev => {
      setUploadFile({ name: file.name, dataUrl: ev.target.result, type: file.type });
      setForm(f => ({ ...f, name: f.name || file.name.replace(/\.[^/.]+$/,''), url: ev.target.result }));
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const save = () => {
    if (!form.name.trim() || (!form.url.trim() && !uploadFile)) return;
    const entry = { id: editing==='new' ? uid() : editing, name: form.name.trim(), url: form.url.trim(), category: form.category, description: form.description.trim(), addedAt: new Date().toISOString(), isUpload: !!uploadFile, fileName: uploadFile?.name || '' };
    const next = editing==='new' ? [...files, entry] : files.map(f => f.id===editing ? entry : f);
    update({ ...p, projectFiles: next });
    close();
  };

  const del = (id) => update({ ...p, projectFiles: files.filter(f=>f.id!==id) });
  const grouped = FILE_CATEGORIES.map(cat => ({ ...cat, files: files.filter(f => f.category===cat.id) }));
  const hasAnyFile = files.length > 0;

  const openFile = (f) => {
    if(!f.url) return;
    if(f.isUpload && f.url.startsWith('data:')){
      try {
        const arr=f.url.split(','); const mime=arr[0].match(/:(.*?);/)[1];
        const bstr=atob(arr[1]); let n=bstr.length; const u8arr=new Uint8Array(n);
        while(n--) u8arr[n]=bstr.charCodeAt(n);
        const blob=new Blob([u8arr],{type:mime});
        const blobUrl=URL.createObjectURL(blob);
        window.open(blobUrl,'_blank');
        setTimeout(()=>URL.revokeObjectURL(blobUrl),10000);
      } catch(e){ window.open(f.url,'_blank'); }
    } else {
      window.open(f.url,'_blank','noopener,noreferrer');
    }
  };

  return (
    <div style={{ padding:16 }}>
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:16 }}>
        <div>
          <Lbl style={{ marginBottom:2 }}>PROJECT FILES</Lbl>
          <div style={{ fontFamily:"'JetBrains Mono',monospace", fontSize:10, color:C.t3 }}>{files.length} file{files.length!==1?'s':''} · Click any file to open</div>
        </div>
        <button onClick={()=>openAdd()} style={{ ...BS(C.amber), padding:'8px 16px', fontSize:13 }}>+ ADD FILE</button>
      </div>

      {editing && (
        <div style={{ background:C.surface, border:'1px solid '+C.amber, borderRadius:12, padding:20, marginBottom:20 }}>
          <div style={{ fontFamily:"'Barlow Condensed',sans-serif", fontWeight:800, fontSize:18, letterSpacing:1, marginBottom:16 }}>{editing==='new'?'ADD FILE':'EDIT FILE'}</div>
          <label style={LS}>FILE CATEGORY</label>
          <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(170px,1fr))', gap:8, marginBottom:14 }}>
            {FILE_CATEGORIES.map(cat=>(
              <button key={cat.id} onClick={()=>setForm(f=>({...f,category:cat.id}))}
                style={{ background:form.category===cat.id?cat.color+'20':C.bg, border:'1px solid '+(form.category===cat.id?cat.color:C.border), borderRadius:8, padding:'8px 10px', cursor:'pointer', textAlign:'left', display:'flex', alignItems:'center', gap:6 }}>
                <span style={{ fontSize:16 }}>{cat.icon}</span>
                <div style={{ fontFamily:"'Barlow Condensed',sans-serif", fontWeight:700, fontSize:11, color:form.category===cat.id?cat.color:C.t1 }}>{cat.label}</div>
              </button>
            ))}
          </div>
          <label style={LS}>FILE NAME *</label>
          <input value={form.name} onChange={setF('name')} placeholder="e.g. Architectural Plans Rev 3" style={IS({marginBottom:14})} />
          <label style={LS}>FILE LINK (Google Drive, Dropbox, SharePoint…)</label>
          <input value={form.url} onChange={setF('url')} placeholder="https://drive.google.com/file/..." style={IS({marginBottom:8})} />
          <div style={{ display:'flex', alignItems:'center', gap:10, marginBottom:14 }}>
            <div style={{ flex:1, height:1, background:C.border }}/><div style={{ fontFamily:"'JetBrains Mono',monospace", fontSize:10, color:C.t3 }}>OR UPLOAD FILE (max 5MB)</div><div style={{ flex:1, height:1, background:C.border }}/>
          </div>
          <input type="file" ref={fileRef} onChange={handleFileUpload} style={{ display:'none' }} />
          <button onClick={()=>fileRef.current?.click()} style={{ width:'100%', background:C.bg, border:'2px dashed '+C.border, borderRadius:8, padding:'12px', cursor:'pointer', color:C.t2, fontFamily:"'Barlow Condensed',sans-serif", fontWeight:700, fontSize:13, letterSpacing:1, marginBottom:14, display:'flex', alignItems:'center', justifyContent:'center', gap:8 }}>
            📎 {uploadFile ? "✓ "+uploadFile.name : 'CHOOSE FILE TO UPLOAD'}
          </button>
          <label style={LS}>DESCRIPTION (optional)</label>
          <input value={form.description} onChange={setF('description')} placeholder="e.g. Approved by council May 2025" style={IS({marginBottom:16})} />
          <div style={{ display:'flex', gap:10 }}>
            <button onClick={close} style={{ ...BS('transparent',C.t2), flex:1, border:'1px solid '+C.border, padding:'11px' }}>CANCEL</button>
            <button onClick={save} disabled={!form.name.trim()||(!form.url.trim()&&!uploadFile)} style={{ ...BS(C.amber), flex:2, padding:'11px', opacity:(!form.name.trim()||(!form.url.trim()&&!uploadFile))?0.5:1 }}>
              {editing==='new'?'ADD FILE':'SAVE CHANGES'}
            </button>
          </div>
        </div>
      )}

      {!hasAnyFile && !editing && (
        <div style={{ textAlign:'center', padding:'40px 0', color:C.t3 }}>
          <div style={{ fontSize:48, marginBottom:14 }}>📁</div>
          <div style={{ fontFamily:"'Barlow Condensed',sans-serif", fontWeight:700, fontSize:20, color:C.t2, marginBottom:8 }}>NO FILES YET</div>
          <div style={{ fontSize:14, marginBottom:20 }}>Add links to plans, permits, contracts and other project documents</div>
          <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(180px,1fr))', gap:10, maxWidth:520, margin:'0 auto' }}>
            {FILE_CATEGORIES.map(cat=>(
              <button key={cat.id} onClick={()=>openAdd(cat.id)} style={{ background:C.surface, border:'1px solid '+C.border, borderRadius:10, padding:'14px', cursor:'pointer', textAlign:'center' }}>
                <div style={{ fontSize:26, marginBottom:6 }}>{cat.icon}</div>
                <div style={{ fontFamily:"'Barlow Condensed',sans-serif", fontWeight:700, fontSize:12, color:C.t1 }}>{cat.label}</div>
                <div style={{ fontFamily:"'JetBrains Mono',monospace", fontSize:9, color:C.t3, marginTop:4 }}>+ ADD FILE</div>
              </button>
            ))}
          </div>
        </div>
      )}

      {hasAnyFile && grouped.map(cat => {
        if (!cat.files.length) return null;
        return (
          <div key={cat.id} style={{ marginBottom:22 }}>
            <div style={{ display:'flex', alignItems:'center', gap:10, marginBottom:10 }}>
              <span style={{ fontSize:18 }}>{cat.icon}</span>
              <div style={{ fontFamily:"'Barlow Condensed',sans-serif", fontWeight:700, fontSize:14, color:cat.color, letterSpacing:1 }}>{cat.label.toUpperCase()}</div>
              <div style={{ flex:1, height:1, background:C.border }}/>
              <button onClick={()=>openAdd(cat.id)} style={{ background:'transparent', border:'1px solid '+cat.color+'50', borderRadius:5, padding:'3px 10px', cursor:'pointer', fontFamily:"'Barlow Condensed',sans-serif", fontWeight:700, fontSize:10, color:cat.color, letterSpacing:1 }}>+ ADD</button>
            </div>
            <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(200px,1fr))', gap:10 }}>
              {cat.files.map(f => (
                <div key={f.id} style={{ background:C.surface, border:'1px solid '+C.border, borderRadius:10, overflow:'hidden', boxShadow:'0 1px 4px rgba(0,0,0,0.06)' }}>
                  <button onClick={()=>openFile(f)} style={{ display:'block', width:'100%', textAlign:'left', background:'transparent', border:'none', cursor:f.url?'pointer':'default', padding:'14px 14px 10px' }}>
                    <div style={{ display:'flex', alignItems:'flex-start', gap:10 }}>
                      <div style={{ width:40, height:40, borderRadius:8, background:cat.color+'20', border:'1px solid '+cat.color+'40', display:'flex', alignItems:'center', justifyContent:'center', fontSize:20, flexShrink:0 }}>{getFileIcon(f.url)}</div>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontFamily:"'Barlow Condensed',sans-serif", fontWeight:700, fontSize:15, color:C.t1, lineHeight:1.2, marginBottom:3 }}>{f.name}</div>
                        {f.description && <div style={{ fontSize:11, color:C.t3, lineHeight:1.3 }}>{f.description}</div>}
                      </div>
                    </div>
                    <div style={{ display:'flex', alignItems:'center', gap:5, marginTop:8, padding:'6px 8px', background:cat.color+'12', borderRadius:6 }}>
                      <span style={{ fontSize:11 }}>🔗</span>
                      <div style={{ fontFamily:"'JetBrains Mono',monospace", fontSize:9, color:cat.color, letterSpacing:1, fontWeight:600 }}>OPEN IN NEW WINDOW</div>
                    </div>
                  </button>
                  <div style={{ borderTop:'1px solid '+C.border, padding:'6px 10px', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                    <div style={{ fontFamily:"'JetBrains Mono',monospace", fontSize:9, color:C.t3 }}>{f.addedAt ? new Date(f.addedAt).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'2-digit'}) : ''}</div>
                    <div style={{ display:'flex', gap:4 }}>
                      <button onClick={()=>openEdit(f)} style={{ background:'transparent', border:'none', cursor:'pointer', fontSize:13, padding:'2px 4px' }}>✏️</button>
                      <button onClick={()=>del(f.id)} style={{ background:'transparent', border:'none', color:C.t3, cursor:'pointer', fontSize:16, lineHeight:1, padding:'0 2px' }}>×</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      })}

      {hasAnyFile && (
        <div style={{ marginTop:10 }}>
          <Lbl style={{ marginBottom:10 }}>ADD MORE FILES</Lbl>
          <div style={{ display:'flex', flexWrap:'wrap', gap:8 }}>
            {grouped.filter(cat=>!cat.files.length).map(cat=>(
              <button key={cat.id} onClick={()=>openAdd(cat.id)} style={{ background:C.surface, border:'1px solid '+C.border, borderRadius:8, padding:'8px 14px', cursor:'pointer', display:'flex', alignItems:'center', gap:8 }}>
                <span style={{ fontSize:16 }}>{cat.icon}</span>
                <div style={{ fontFamily:"'Barlow Condensed',sans-serif", fontWeight:700, fontSize:12, color:C.t2 }}>{cat.label}</div>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ── HELPERS ───────────────────────────────────────────────────────────────────
function Lbl({children,style}){return <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:11,letterSpacing:2,color:C.t3,marginBottom:12,...style}}>{children}</div>;}
function Chip({color,onClick,children}){return <button onClick={onClick} style={{padding:'3px 10px',borderRadius:6,border:'1px solid '+color+'40',background:color+'15',color,cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,fontSize:10,letterSpacing:1}}>{children}</button>;}
function Splash(){
  const [slow,setSlow]=useState(false);
  useEffect(()=>{ const t=setTimeout(()=>setSlow(true),4000); return()=>clearTimeout(t); },[]);
  return(
    <div style={{minHeight:'100vh',background:'#F4F6F9',display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',gap:12}}>
      <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:20,letterSpacing:4,color:C.amber}}>LOADING…</div>
      {slow&&<div style={{fontFamily:"'Barlow',sans-serif",fontSize:13,color:'#94A3B8',textAlign:'center',maxWidth:280}}>Connecting to server… if this takes too long, check your internet connection.</div>}
    </div>
  );
}

// ── ERROR BOUNDARY ────────────────────────────────────────────────────────────
export class ErrorBoundary extends React.Component {
  constructor(props){ super(props); this.state={error:null}; }
  static getDerivedStateFromError(e){ return {error:e}; }
  render(){
    if(this.state.error) return(
      <div style={{minHeight:'100vh',background:'#F4F6F9',display:'flex',alignItems:'center',justifyContent:'center',padding:20}}>
        <div style={{background:'#fff',border:'1px solid #E2E8F0',borderLeft:'4px solid #DC2626',borderRadius:12,padding:28,maxWidth:500,width:'100%'}}>
          <div style={{fontSize:32,marginBottom:12}}>⚠️</div>
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:22,color:'#0D1B3E',marginBottom:8}}>SOMETHING WENT WRONG</div>
          <div style={{fontSize:13,color:'#475569',marginBottom:16,fontFamily:"'Barlow',sans-serif"}}>{this.state.error?.message||'An unexpected error occurred.'}</div>
          <button onClick={()=>window.location.reload()} style={{background:'#B8960C',border:'none',borderRadius:8,padding:'11px 24px',cursor:'pointer',fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,fontSize:14,color:'#000',letterSpacing:1}}>RELOAD APP</button>
        </div>
      </div>
    );
    return this.props.children;
  }
}

export default App;
